    // open bin offers a decent home.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_options = if fitting_bins_count > 0 && fit_ratio < 0.5 { 1.0 } else { 0.0 };
