    // Lookahead coupling: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 1.0 {
            score -= 45.0;
        } else if nxt <= post_residual as f64 {
            score -= 10.0 * (nxt / (post_residual as f64 + 1.0));
        } else {
            // Next item won't fit here: mild penalty proportional to wasted lookahead potential.
            score += 4.0 * ((nxt - post_residual as f64) / 100.0);
        }
    }

    // Scarcity: if this is the only bin that fits, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer the tightest, add mild competition pressure.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate modulation: empty bin gets a baseline penalty that shrinks
    // when few bins are open or many items remain (exploration vs exploitation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let exploration = ((open_bins_count as f64 + 1.0).ln() * 6.0) + (1.0 - progress) * 10.0;
        score += 22.0 + exploration;
    }

    // Global state: penalize bins whose residual deviates badly from the mean residual
    // (keeps the open-bin pool homogeneous, easier to close out later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late-stream pressure: as the stream ends, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins with larger residual when item is small relative to it (avoid fragmenting big bins with tiny items).
    if (item_size as f64) < 0.35 * residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Cubic coupling: tight fits become exponentially more valuable late in stream.
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical future items.
    let dead = (norm_pr * 10.0).powi(2) * (1.0 - (norm_pr * 10.0).min(1.0));
    score += 40.0 * dead;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // New-bin candidate: penalize mildly early, more when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Smooth mean-residual coupling: prefer bins deviating from mean when mean is low.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: dead space that is a
    // multiple of 10 is reusable by typical items; odd/prime remainders are worse.
    let class = post_residual % 10;
    let class_penalty: f64 = match class {
        0 => -6.0,
        5 => -2.0,
        1 | 3 | 7 | 9 => 4.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Exact fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tiny unusable residue (< 10, the minimum item size) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division thresholds on post_residual: bucket the leftover
    // space into capacity fractions and prefer bins whose leftover still
    // admits a "half-class" (>= 50) or "quarter-class" (>= 25) item.
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual >= 25 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain of harmonic classes).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= if slack % 10 == 0 { 10.0 } else { 4.0 };
            if slack > 0 && slack < 10 {
                score += 6.0;
            }
        } else {
            // Next item won't fit here; leftover should still be a
            // "clean class" for future items.
            score += (post_residual % 10) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when
    // open bins all give bad fits, but reward it early in the stream or
    // when mean residual across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 - 25.0 * (1.0 - progress) - fragmentation.min(10.0);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps
    let dead_threshold = 12.0f64; // gaps below smallest item (size 10) are dead
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 200.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize moderate gaps that are unlikely to fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Open bins pressure: prefer reusing bins when many are open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 40.0;
    }

    // New bin candidate: make it moderately unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 250.0;
        // but attractive if no open bin fits (last chance is the new bin itself)
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Progression: tighten packing slightly as stream advances
    score *= 1.0 + 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 100.0; // exact match: place here
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 10.0;
    }

    // Reward bins tighter than average (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Penalize opening a new bin when other bins could fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + 5.0 * fitting_bins_count as f64;
        } else {
            score -= 20.0; // last resort: new bin is fine
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact-fit jackpot: zero waste is extremely attractive.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no future item (>=10) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 14.0 * chain_fit;
        } else {
            // Post-residual too small for the next item: mild penalty unless it was a perfect fit.
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap; late stream: prefer filling existing bins.
        let openness = 1.0 - progress;
        score += 20.0 * (1.0 - openness);
        // Penalize opening a new bin when many bins already fit the item.
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Fragmentation guard: penalize bins whose residual deviates far above the mean
    // (keeps large residuals available for large future items).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Mild preference for bins with larger residuals when item is large.
    if item_size > bin_capacity / 2 {
        score -= 0.05 * bin_residual as f64;
    }

    // Time-horizon scaling: as the stream nears its end, waste matters more.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * horizon * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Base: reward small post_residual (tight fit), reward grows quadratically/cubically.
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Progress coupling: early on, prefer flexibility (larger residuals ok); later, demand tight fits.
    let tightness = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score -= tightness * (cap - pr) * 0.8;
    score += (1.0 - tightness) * pr * 0.4;

    // Penalize residuals that become unusable for typical items, smoothly.
    let dead = if pr > 0.0 { (cap / pr).ln().max(0.0) } else { 0.0 };
    score += 2.0 * dead * (0.5 + tightness);

    // Lookahead: reward leaving room for the next item, smoothly decaying with post_residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = (pr - n).max(0.0);
        score -= 1.5 * (fit_next / cap) * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + tightness);
    }

    // Mild crowd penalty: many open bins with slack -> discourage spreading residual.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * pr_norm * mean_residual / cap;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - tightness) + 10.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse for small classes.
    let post = post_residual as u32;
    let class = post / 10; // integer division threshold class
    let remainder = post % 10;

    // Penalize small unusable remainders (dead space), reward near-zero or large residuals.
    if post > 0 && post < 10 {
        score += 30.0; // tiny sliver: worst outcome
    } else if post == 0 {
        score -= 50.0; // perfect fit: best possible
    } else {
        // Non-linear decay: larger usable residuals are progressively less penalized
        score += 10.0 / (1.0 + class as f64);
        // Modulo-5 harmonic bonus: residuals divisible by 5 pair better with typical sizes
        if remainder % 5 == 0 {
            score -= 5.0;
        }
        if remainder == 0 {
            score -= 5.0; // clean decade residual
        }
    }

    // Fraction-of-capacity coupling: residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    if frac < 0.1 && frac > 0.0 {
        score += 25.0 * (0.1 - frac); // gradient penalty near dead zone
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post == 0 {
                score -= 35.0;
            } else if nxt_post < 10 {
                score += 10.0; // would create sliver next round
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here: slight penalty unless we're closing bin anyway
            score += 6.0;
        }
    } else {
        // Last item: any nonzero residual is pure waste
        if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in stream: consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Many open bins: discourage spreading; prefer tightest fits.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs() / cap;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= cap as f64 * 0.5; // forced: must open
        } else if post_residual as f64 / cap > 0.4 && next_item_size as f64 >= post_residual as f64 {
            score -= cap as f64 * 0.25; // fresh bin preserves room for big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are useless, penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (waste <= 5) strongly.
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: only attractive if this bin's fit is terrible.
    if bin_residual == bin_capacity {
        // Baseline handicap relative to typical post_residual; beaten only by bad fits.
        score += 35.0 + mean_residual * 0.2;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit post_residual but post_residual is tiny, slight penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 8.0;
    }

    // Prefer bins whose residual is closest to item (tightest fit) via relative measure.
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item (perfect pairing)
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let ni = next_item_size as i64;
        let diff = (pr - ni).abs() as f64;
        if pr == ni {
            score -= 40.0; // perfect 2-step match
        } else if pr >= ni {
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item cannot follow into this bin: penalize dead space relative to gap
            score += (ni - pr) as f64 * 0.6;
        }
    }

    // Relative to mean residual: bins tighter than average are good targets
    let resid = post_residual as f64;
    score += (resid - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight penalty for opening a new bin when many bins already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // But allow new bin if current post-fit would be very tight for the lookahead
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Progress-based mild tightening: prefer tighter fits later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += resid * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space penalty is super-linear).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Exact fill is a jackpot.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward packing them together; otherwise penalize leaving a gap that
    // matches neither the next item nor anything useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Gap too small for next item: penalize proportionally to wasted space.
            score += 0.25 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when existing
    // fits are poor (large post_residual) or when the item is big and many
    // bins are already open. Otherwise discourage proliferation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = frac > 0.35;
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if poor_fit || big_item {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 50.0 + open_bins_count as f64;
        }
    }

    // Global pressure: when mean residual across open bins is high, prefer
    // consolidating into fuller bins (higher residual here = worse choice).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be pickier about fragmentation;
    // late in the stream, just get items placed anywhere that fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * prn * prn);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals slightly; late, penalize dead space harder.
    score += 18.0 * prn * prn * (0.5 + progress);

    // Reward near-perfect fills quadratically.
    score -= 30.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
