    }

    // Penalize bins far from mean residual (fragmentation avoidance), smooth term.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild preference for consolidating into fewer bins when many are open.
    score += 2.0 * (open_bins_count as f64).ln() * prn;

