    // it's a "lonely" bin; using it tightens the global state.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.05;
    }

    // Modulo coupling between item and residual: harmonic size classes.
    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0; // aligned decimal classes keep future fits clean
    }

    score
