        // Fresh-bin penalty scaled by how much open capacity already exists.
        let open_cap = open_bins_count as f64 * mean_residual;
        if open_cap > item_size as f64 * 2.0 {
            score += 3.0;
        }
        // Small items should never trigger a new bin while open bins can host them.
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
