    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55
        && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Triple-chain probe — deep chains instead of shallow pairs.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Adaptive tightness — when bins are nearly full overall, use emptiest
    // fitting bins first so tight bins stay available for small items.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // NEW mutation: residual-entropy steering — when the next item is small
    // relative to capacity, gently prefer bins whose post-residual is a
    // multiple of small common sizes, keeping future fill options open.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // NEW mutation: sprawl-aware new-bin gate — when many bins are open
    // relative to stream progress, make fresh bins costlier unless the item
    // is large enough to justify a dedicated bin.
    if bin_residual == bin_capacity {
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
    }

    score
}

