    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding around fleet mean.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // NEW mutation: mid-stream compaction surge — during the densest packing
    // window, exact closures and near-closures earn an extra discount, while
    // mid-sized stranded residuals get a sharper penalty.
    if progress > 0.2 && progress < 0.9 {
        if post_residual == 0 {
            score -= 3.0;
        } else if post_residual <= twentieth && bin_residual != bin_capacity {
            score -= 2.0;
        } else if post_residual > fifth && post_residual < next_item_size.max(1) as u32 * 2 {
            score += 2.0;
        }
    }

    // NEW mutation: fill-efficiency race — prefer the bin whose fill ratio
    // (item / residual) is highest, normalized so it doesn't dominate.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.8 {
            score -= (fill - 0.8) * 10.0;
        } else if fill < 0.3 {
            score += 1.5;
        }
    }

    score
}

