    if next_item_size > 0 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // MUTATION C: best-fit-of-fleet normalization — discount bins whose
    // post_residual is the tightest relative to how many bins could fit.
    if fitting_bins_count >= 1 && bin_residual != bin_capacity {
        score -= (fitting_bins_count as f64).ln().max(0.0) * (pr / cap) * 6.0;
