    // Residual-reusability forecast — a post-residual that still admits
    // the fleet's mean-sized item keeps future options open.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // MUTATION: best-fit sharpening — among bins that can host the next item,
    // discount those with the smallest resulting slack beyond the next item.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let slack = post_residual - next_item_size;
        if slack <= 2 {
            score -= 4.0;
        }
    }

    // MUTATION: anti-sprawl — when open bins far exceed the packed fraction,
    // add pressure to fill existing bins harder.
    let packed_frac = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > packed_frac * total_items.max(1) as f64 {
        score += pr * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
