    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let ni = next_item_size as i64;
        let diff = (pr - ni).abs();
        if diff == 0 {
            score -= 40.0; // perfect 2-chain
        } else if pr >= ni {
            // slack after the next item would also fit: scale by tightness
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here -> dead space penalty proportional to leftover
            score += 15.0 + (ni - pr) as f64 * 0.5;
        }
    }

    // Prefer bins whose residual deviates from mean in a useful way
    let mean_dev = post_residual as f64 - mean_residual;
    score += 0.15 * mean_dev;

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits anywhere
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // discourage opening a new bin when open bins can fit
            score += 60.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Mild pressure to keep many bins tight as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Capacity-relative dead-space bands with fine near-exact tiers.
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 34.0; // perfect fit
    } else if post_residual < fortieth {
        score += 5.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual < twentieth {
        score += 11.0 + (twentieth - post_residual) as f64 * 0.04;
    } else if post_residual < tenth {
        score += 28.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 38.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score -= 8.0;
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0;
        } else if slack < cap * 0.1 {
            score -= 14.0;
        } else if slack < cap * 0.25 {
            score -= 6.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 8.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Last-chance bin: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Scarcity coupling: prefer reuse when few bins fit.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 17.0 + 10.0 * progress;
        if item_size as f64 > cap * 0.7 {
            score -= 13.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 9.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        // Fresh bin when reuse would strand a sliver the next item can't use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 9.0;
        }
        // Discourage fresh bins when many open bins fit.
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.5;
        }
        // Fresh-bin sprawl guard: don't open bins when fleet is already wide.
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        // Exact two-item fill from a fresh bin is excellent.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        // Small items shouldn't waste a fresh bin when anything fits them.
        if item_size <= tenth && fitting_bins_count >= 1 {
            score += 5.0;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
    }

    // Mean-residual deviation: prefer above-mean residual bins.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    // Decimal alignment keeps future fits clean.
    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Waste-forecast: penalize unusable residual, stronger early in stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control: tighten residual preference when bins outpace progress.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus — near-exact complement tiers.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency — big items should not strand space.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain: reward bins that can absorb item + next.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap: tiny dead slivers, horizon-weighted.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness: when fleet residuals are small, squeeze harder.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard: barely-over-next residues are awkward.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding: residues near fleet mean are predictable/reusable.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index: many open bins + unusable residue = penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue: tight residues should absorb big items.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: fresh-bin mean-residual veto — when fleet residuals are tiny,
    // opening a new bin strands capacity; prefer squeezing open bins harder.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count >= 1
        && item_size as f64 <= cap * 0.5 && mean_residual < cap * 0.12 {
        score += 5.0;
    }

    // NEW: horizon-aware fresh-bin discount — late in the stream, a fresh bin
    // whose leftover can host the next item is a safe compaction move.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_left = bin_capacity.saturating_sub(item_size);
        if fresh_left >= next_item_size {
            score -= (1.0 - progress) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that cannot fit the next item (lookahead-aware waste).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward bins whose leftover exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 8.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score -= 20.0 * progress * tight;

    // Compare residual to mean: prefer bins with below-average residual (nearly full).
    let rel = bin_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no decent open-bin fit exists (post_residual would be very small anyway).
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 55.0; // base penalty: prefer existing bins
        score -= 70.0 * big_item * big_item; // large items justify fresh bins
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0; // fresh bin can still host next item
        }
        if fitting_bins_count <= 1 {
            score -= 40.0; // poor alternatives make a new bin fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
