            let excess = (post_residual as f64).max(mean_residual) - mean_residual;
            score += excess * 0.04;
        }
    }

    // NEW (gen 19): new-bin gate — only open a fresh bin when the item is large
    // or the fleet genuinely cannot host it; penalize sprawl harder mid-stream.
    if bin_residual == bin_capacity {
        let fleet_fill = 1.0 - mean_residual / cap;
        if fleet_fill > 0.9 && item_size as f64 <= cap * 0.4 {
            score += 3.5 * (1.0 - progress);
        }
        if fitting_bins_count == 0 && item_size as f64 > cap * 0.3 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    score
}

