            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: dead-space ratio refinement — extra pressure when the leftover
    // fraction is small enough to be practically unusable mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 {
        let leftover_frac = post_residual as f64 / cap;
        if leftover_frac < 0.06 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score += (0.06 - leftover_frac) * 40.0 * (0.5 + 0.5 * mid);
        }
    }

    // NEW: mid-stream tight-fit escalation — reward near-exact fills more
    // when residual variance across the fleet is low (predictable stream).
    if bin_residual != bin_capacity && post_residual > 0 && post_residual <= twentieth {
        score -= 2.5 * (1.0 - progress);
    }

    score
}

