    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: absolute-dead-space sweep — residual that no plausible future item
    // (bounded by next_item_size and mean residual) can consume is penalized
    // with horizon weighting, targeting the diagnosed dead-space weakness.
    if post_residual > 0 && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let plausible_max = (next_item_size as f64).max(mean_residual).max(cap * 0.1);
        if (post_residual as f64) < plausible_max * 0.5 {
            score += 3.0 * horizon * (1.0 - post_residual as f64 / (plausible_max * 0.5));
        }
    }

    // NEW: inter-bin complementarity — prefer leaving residuals that differ
    // from the fleet mean by a reusable margin (avoids uniform stranded gaps).
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap as f64 > cap * 0.3 {
            score += 2.0;
        }
    }

    score
}

