    if post_residual % 25 == 0 { score -= 1.5; }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 32.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Last-chance bin: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 17.0 + 10.0 * progress;
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        if item_size as f64 > cap * 0.85 && fitting_bins_count == 0 {
            score -= 6.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5 {
            if mean_residual < cap * 0.12 {
                score -= 5.0;
            }
        }
        if next_item_size > 0 {
            let fresh_left3 = bin_capacity.saturating_sub(item_size);
            if fresh_left3 < next_item_size && mean_residual >= next_item_size as f64 {
                score += 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // NEW: prefer fresh bin when a best-fit would strand a mid-size residue
        // that no known next item can consume, given ample fleet slack exists.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_left = bin_capacity.saturating_sub(item_size);
            if best_left >= next_item_size && best_left < next_item_size * 2
                && mean_residual > best_left as f64 {
                score -= 3.0;
            }
        }
    }

    // Mean-residual deviation.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: dead-space ratio guard — penalize placements whose post-residual is
    // a large fraction of the item itself (hard-to-reuse slivers), scaled by
    // remaining stream so early bad shapes are punished harder.
    if bin_residual != bin_capacity && post_residual > 0 && post_residual <= tenth {
        let sliver_ratio = post_residual as f64 / item_size.max(1) as f64;
        if sliver_ratio > 0.3 {
            score += (sliver_ratio - 0.3) * 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer larger post_residual (keep bins flexible).
    // Late: prefer small post_residual (fill bins tightly).
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);
    let mut score = w_early * (norm_pr.powi(2) * 40.0 + norm_pr * 10.0)
                  + w_late * (norm_pr.powi(2) * 120.0 - norm_pr * 60.0)
                  + pr * 0.5;

    // Dead-space penalty: cubic in normalized post_residual.
    score += norm_pr.powi(3) * 80.0;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: bonus if next item fits exactly into resulting residual.
    if next_item_size > 0 {
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 20.0;
        }
    }

    // New empty bin candidate: penalize mildly early, more when many bins open,
    // but allow it when current bin would leave awkward residual.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64 + 50.0 * progress;
        if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
            score -= 70.0;
        }
    }

    // Prefer bins with residuals near the mean (balanced usage).
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 38.0;
        if next_item_size > 0 && item_size <= tenth {
            score -= 4.0;
        }
    }

    // Fine-grained dead-space tiers (borrowed banding, tightened)
    if post_residual > 0 {
        if post_residual < fortieth {
            score += 6.0 + (fortieth - post_residual) as f64 * 0.03;
        } else if post_residual < twentieth {
            score += 12.0 + (twentieth - post_residual) as f64 * 0.04;
        } else if post_residual < tenth {
            score += 30.0 + (tenth - post_residual) as f64 * 0.05;
        } else if post_residual < fifth {
            score += 38.0 + (fifth - post_residual) as f64 * 0.07;
        } else if post_residual <= third {
            score += 4.0;
        } else if post_residual <= bin_capacity / 2 {
            score -= 3.0;
        } else {
            score -= 8.0;
        }
    }

    // Integer-division harmonic classes
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Open bins pressure
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 17.0;
    }
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.5;
    }

    // Lookahead with graded slack reward (sharpened)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 32.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Two-item lookahead chain
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 { score -= 8.0; }
            else if slack2 <= tenth { score -= 4.0; }
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 17.0 + 11.0 * progress;
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        if item_size as f64 > cap * 0.85 && fitting_bins_count == 0 {
            score -= 6.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
        if next_item_size > 0 {
            if fresh_left == 0 { score -= 15.0; }
            else if fresh_left <= twentieth { score -= 6.0; }
            if bin_capacity - item_size == next_item_size { score -= 8.0; }
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5
            && mean_residual < cap * 0.12 {
            score -= 5.0;
        }
    }

    // Mean-residual deviation
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.2;
    }

    // Waste-forecast: unusable residual, stronger early
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        score += 5.0 + 4.5 * (1.0 - progress);
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Global sprawl control
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Multi-fit dilution
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Strand-ratio discount
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.06 * (1.0 - progress);
        }
    }

    // Dead-space delta coupling vs fleet average
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let this_waste = post_residual as f64;
        if this_waste < mean_residual {
            score -= (mean_residual - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - mean_residual) * 0.05 * (1.0 - progress);
        }
    }

    // Residual-entropy banding
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Exact-fill sweep
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Adaptive tightness
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Progression: tighten packing as stream advances
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes modulo
    // common divisors of typical item sizes (e.g. mod 10, mod 5, mod 2).
    // Residues that are "harmonically compatible" with common item sizes
    // are more likely to be filled later, so penalize them less.
    let cap = bin_capacity as f64;

    // --- mod-10 class of post_residual ---
    let r10 = post_residual % 10;
    // Residue 0 (exact multiple of 10) is the most compatible: reward it.
    score -= match r10 {
        0 => 6.0,
        5 => 3.0,                 // half-multiple: still fairly compatible
        2 | 4 | 6 | 8 => 0.0,     // even residues: neutral
        _ => 2.5,                 // odd non-5 residues: awkward dead space
    };

    // --- integer-division thresholds on post_residual ---
    // Dead space below the smallest plausible item is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Space in [10, 20) can host only tiny items: mild penalty.
    else if post_residual < 20 {
        score += 6.0;
    }
    // Large post_residual is fine (bin stays flexible): small reward.
    else if post_residual > 50 {
        score -= 3.0;
    }

    // --- coupling with next_item_size (lookahead) ---
    if next_item_size > 0 {
        // Perfect harmonic match: next item exactly fills this bin.
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // Next item fits with a harmonically clean leftover (mod 10 == 0).
        else if post_residual > next_item_size
            && (post_residual - next_item_size) % 10 == 0
        {
            score -= 12.0;
        }
        // Next item cannot fit here anyway: no coupling needed.
        // Next item would fit but leave a dead sliver (< 10): penalize.
        else if post_residual >= next_item_size
            && post_residual - next_item_size < 10
        {
            score += 10.0;
        }
        // Harmonic gcd-style compatibility: gcd(next, post) large => flexible.
        let mut a = next_item_size;
        let mut b = post_residual.max(1);
        while b != 0 {
            let t = a % b;
            a = b;
            b = t;
        }
        let gcd = a as f64;
        score -= (gcd / 10.0).min(4.0);
    }

    // --- last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits the item; strongly prefer using it
        // over opening a new bin, unless it creates tiny dead space.
        if post_residual >= 10 || post_residual == 0 {
            score -= 30.0;
        }
    }

    // --- new-bin candidate handling ---
    if bin_residual == bin_capacity {
        // A fresh empty bin is attractive if existing bins would be badly
        // fragmented (low mean residual spread, many awkward classes) or
        // if item is large. Base cost of a new bin:
        score += 15.0;
        // Prefer new bin when current item is large relative to capacity.
        score += (item_size as f64 / cap) * 10.0;
        // If many bins already open and mean residual is high, reusing is
        // cheap, so make the new bin less attractive.
        score += (mean_residual / cap) * 20.0;
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If the item is harmonically large (close to capacity), new bin is good.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // --- mild global pressure to consolidate ---
    score += (open_bins_count as f64) * 0.05;

    // Prefer bins whose residual is far below mean (they are "tighter",
    // i.e. closer to full): reward using them.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Capacity-relative dead-space bands with fine near-exact tiers.
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 36.0;
    } else if post_residual < fortieth {
        score += 6.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual < twentieth {
        score += 12.0 + (twentieth - post_residual) as f64 * 0.04;
    } else if post_residual < tenth {
        score += 30.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 38.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score -= 8.0;
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 32.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Last-chance bin: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 17.0 + 10.0 * progress;
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        if item_size as f64 > cap * 0.85 && fitting_bins_count == 0 {
            score -= 6.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5 {
            if mean_residual < cap * 0.12 {
                score -= 5.0;
            }
        }
        if next_item_size > 0 {
            let fresh_left3 = bin_capacity.saturating_sub(item_size);
            if fresh_left3 < next_item_size && mean_residual >= next_item_size as f64 {
                score += 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // New: prefer opening a fresh bin when the fleet's mean residual can't
        // absorb this item anywhere usefully (deep-dead-space escape hatch).
        if fitting_bins_count >= 1 && next_item_size > 0
            && mean_residual < next_item_size as f64 * 0.5
            && item_size as f64 > cap * 0.45 {
            score += 5.0;
        }
    }

    // Mean-residual deviation.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure (tuned up).
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 14.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.5 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.45;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.11 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // New: perfect-fill sweep across the whole chain — prefer bins whose
    // remaining space after this item is a multiple of common small sizes.
    if bin_residual != bin_capacity && post_residual > 0 && post_residual <= twentieth {
        if post_residual % 5 == 0 {
            score -= 2.5 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // New: penalize leaving residuals that no plausible item class can use —
    // residual below 5% of capacity is nearly dead weight unless exact.
    if bin_residual != bin_capacity && post_residual > 0 && post_residual < bin_capacity / 25 {
        score += 1.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste ratio penalty).
    if bin_residual > 0 {
        score += (item_size as f64 / bin_residual as f64) * -15.0 + 15.0;
    }

    // Dead space relative to next item: gap that next item cannot use is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when mean residual is tight
    // (existing bins nearly full) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0
            + mean_residual * 1.5
            + progress * 20.0
            - item_size as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
