pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: bin closes exactly with the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits snugly into the post residual (near-perfect 2-step chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to lookahead: next item cannot follow here.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Reward filling bins tightly relative to the mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable fragments (<10 by classic dead-space rule).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, allow opening fresh bins more freely;
    // later, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
        score += 12.0 * progress;
    }

    score
}

