        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: residual-coverage matching — reward bins whose post-residual closely
    // matches the next item (harmonic fill), scaled by remaining stream.
    if next_item_size > 0 && post_residual > 0 {
        let rel_gap = ((post_residual as f64 - next_item_size as f64) / next_item_size.max(1) as f64).abs();
        if rel_gap < 0.2 {
            score -= (0.2 - rel_gap) * 10.0 * (1.0 - progress * 0.5);
        }
    }

    // NEW: multi-fit congestion — when many bins fit, prefer the one closest to closure.
    if fitting_bins_count >= 4 && post_residual > 0 {
        score += post_residual as f64 * 0.04;
    }

    // NEW: perfect-closure sweep — residual exactly zero is the ultimate goal.
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: quadratic polynomial in post-residual, mildly convex to prefer tight fits.
    let mut score = r * (1.0 + 0.9 * norm_r * norm_r);

    // Smooth coupling of post_residual with stream progress: later in the stream,
    // residual space becomes more valuable (penalize leaving slack).
    let progress_weight = 0.35 * progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += r * progress_weight * 0.5;
    score -= r * progress * 0.25; // late stream: reward tight fills

    // Interaction with mean residual: prefer bins whose post-residual deviates
    // smoothly (quadratically) from the mean, packing similar bins together.
    let dev = (r - mean_residual) / cap;
    score += 12.0 * dev * dev * cap * 0.1;

    // Next-item lookahead: reward post-residual that smoothly matches next item.
    if next_item_size > 0 {
        let diff = (r - next_item_size as f64).abs();
        let fit_quality = 1.0 - (diff / cap).min(1.0);
        score -= 6.0 * fit_quality * fit_quality;
    }

    // Last-chance bonus when this is the only fitting bin (smooth saturation).
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        score -= 8.0 * (1.0 - 1.0 / (fitting_bins_count as f64));
    }

    // Mild penalty for many open bins, scaled by residual left behind.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * r * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
