    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: cubic dead-space surge — residuals that are both small in absolute
    // terms and unusable by next item are prime waste; penalize harder mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size {
        let unusable = post_residual as f64 / cap;
        score += unusable * unusable * 22.0 * (0.5 + 0.5 * (1.0 - progress));
    }

    // NEW: multi-fit preference — if several bins fit, favor the one whose
    // post-residual best matches the next item (tightest reusable leftover).
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
        let reuse_gap = (post_residual - next_item_size) as f64;
        score -= reuse_gap * 0.05;
    }

    // NEW: penalize leaving residual just above half-capacity (hardest to fill).
    if bin_residual != bin_capacity && post_residual > bin_capacity / 2
        && post_residual < third * 2 {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead zones" (tiny slivers that no item of size >=10 can use, or
    // awkward mid-sized gaps) are penalized via modular structure.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: perfect fit (zero residual) is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Class 2: unusable sliver (1..10) — dead space, but at least tight.
    if post_residual >= 1 && post_residual < 10 {
        score -= 20.0;
    }

    // Class 3: usable residual — reward if the next item fits exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 6.0 * (1.0 - slack / cap);
        // Exact lookahead fit is highly desirable.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // Lookahead item won't fit here: mild penalty, worse if residual is large.
        score += 3.0 + 0.05 * pr;
    }

    // Harmonic residue classes on post_residual modulo 10: residuals that are
    // multiples of 10 align with the item-size grid and are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Fraction-of-capacity coupling: filling a bin beyond 70% is valuable.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.7 {
        score -= 6.0 * fill_frac;
    } else if fill_frac < 0.4 {
        // Leaving a bin barely touched wastes capacity.
        score += 5.0 * (0.4 - fill_frac);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only open a new bin when the item is large relative to remaining space
    // in existing bins, or when many bins already fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Large items pack better in fresh bins.
        if item_size >= 60 {
            score -= 10.0;
        }
        // If no other bin fits well (few fitting bins), opening is fine.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If mean residual across open bins is large, reuse them instead.
        if mean_residual > item_size as f64 {
            score += 6.0;
        }
    }

    // Slight preference for bins with residual close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
