        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: dead-space multiplier — penalize residue that no plausible future
    // item can consume (below observed fleet minimum usable size).
    if post_residual > 0 && bin_residual != bin_capacity && next_item_size > 0 {
        let usable_floor = (next_item_size as f64 * 0.6).max(1.0);
        if (post_residual as f64) < usable_floor {
            let horizon = 1.0 - progress;
            score += 3.0 + 5.0 * horizon * (usable_floor - post_residual as f64) / usable_floor;
        }
    }

    // NEW: harmonic dead-space — residue that is a proper divisor of capacity
    // is more likely to be closed by future complementary items.
    if post_residual > 0 && bin_capacity % post_residual == 0 && post_residual <= fifth {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = residual that cannot fit even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Penalize gaps too small for the lookahead item but not tiny either:
    // they are likely to become permanent dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size - post_residual) as f64;
    }

    // Reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: residual barely larger than item.
    let slack = (bin_residual - item_size) as f64;
    score -= 8.0 * (1.0 - slack / bin_capacity as f64);

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless the item would leave
    // a large usable residual relative to current mean residual.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        if post_residual as f64 >= mean_residual {
            score -= 25.0;
        }
    }

    // Late in the stream, tighten up: prefer minimizing waste even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
