    } else if post_residual < tenth {
        score += 24.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 30.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if pr <= cap * 0.5 {
        score -= 3.0;
    } else {
        score -= 8.0;
    }

    // Divisibility keeps residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    // Lookahead chain rewards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 32.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual < bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // Crowding: discourage spreading.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 8.0 * crowding * (pr / cap);

    // Time horizon: later, greedier about tight fits.
    score -= 20.0 * progress * tight;

    // Mean-residual deviation (asymmetric, like best).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score += 55.0 + 10.0 * progress;
        score -= 70.0 * big_item * big_item;
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size { score -= 10.0; }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size);
        if fresh_left % 10 == 0 && fresh_left <= twentieth {
            score -= 6.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual < bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 { score -= 8.0; }
            else if slack2 <= tenth { score -= 4.0; }
        }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual < bin_capacity {
        let waste_ratio = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual < bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual < bin_capacity && open_bins_count > 0 {
        let this_waste = pr;
        if this_waste < mean_residual {
            score -= (mean_residual - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - mean_residual) * 0.05 * (1.0 - progress);
        }
    }

    // Strand-ratio discount.
    if bin_residual < bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.06 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-perfect lookahead match (small gap).
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 25.0 * (1.0 - gap / 10.0);
        }
    }

    // Penalize residuals that are too small to ever be useful (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0 * (10 - post_residual) as f64;
    }

    // Penalize if post_residual can't fit next item but bin_residual could have
    // left a more flexible state relative to mean residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward bins with residual below mean (tight packing) when lookahead fits.
    let mean_gap = mean_residual - post_residual as f64;
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.15 * mean_gap;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if lookahead suggests a clean two-item fill.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 60.0;
        }
    }

    // Slight preference for filling bins as stream progresses.
    score -= 0.05 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Capacity-relative dead-space bands with sharpened near-exact tiers.
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 38.0;
    } else if post_residual < fortieth {
        score += 5.0 + (fortieth - post_residual) as f64 * 0.04;
    } else if post_residual < twentieth {
