    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure (tuned).
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.5 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.45;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        // NEW: extra pressure when the stranded residual cannot host the next
        // item and few bins fit — a sign of poor compaction choice.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
            waste *= 1.25;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= eighth && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: compaction-quality coupling — reward bins whose post-residual stays
    // small relative to both capacity and the next item's needs, weighted by
    // how many bins could fit the item (competition among candidates).
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let usable = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let tightness = 1.0 - pr / cap;
        score -= usable * tightness * (1.5 + fitting_bins_count as f64 * 0.4);
    }

    // NEW: penalize leaving residuals in the awkward 10–20% band that rarely
    // hosts typical items, scaled by remaining stream length.
    if bin_residual != bin_capacity && post_residual > twentieth && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += (post_residual - twentieth) as f64 * 0.08 * horizon;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly rewarded (small dead space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize leaving residuals that are too small to be useful later,
    // but reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins where this item fits best.
        score += 2.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // this bin remains productive; reward it. If next item is large and
    // would need most of a fresh bin, avoid wasting residual capacity.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0 * (1.0 - nxt / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if we strand a big residual.
            score += 0.08 * post_residual as f64 * (nxt / bin_capacity as f64);
        }
    }

    // Global state: with many open bins, consolidation is favored
    // (avoid spreading); with few bins, filling tightly is fine.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 0.6 * pressure;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative (favor tight fits
    // for future flexibility); late in the stream, just close bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - t);

    // New-bin candidate: only attractive when the item is large and no
    // open bin offers a decent home.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_options = if fitting_bins_count > 0 && fit_ratio < 0.5 { 1.0 } else { 0.0 };
        score = 120.0 - 60.0 * large - 30.0 * desperation - 25.0 * poor_options - 15.0 * t;
    }

    score
}

