pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    // Tight-fit reward: smooth function peaking when post_residual is small
    let tight = -2.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize wasting a last-chance bin when it leaves awkward space
    let last_chance = if fitting_bins_count == 1 { -1.5 * (1.0 - norm_pr) } else { 0.0 };

    // Lookahead coupling: reward if next item fits the post residual smoothly
    let n = next_item_size as f64 / cap;
    let lookahead = if next_item_size > 0 { -1.0 * (1.0 - (n - norm_pr) * (n - norm_pr)) } else { 0.0 };

    // Mean residual deviation penalty (smooth quadratic)
    let dev = 0.3 * (norm_pr - mean_residual / cap) * (norm_pr - mean_residual / cap);

    let mut score = pr + 10.0 * poly + tight + last_chance + lookahead + dev;
    score
}

