        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // NEW: penalize opening a bin when fleet slack can absorb this item.
        let fleet_slack = open_bins_count as f64 * mean_residual;
        if fleet_slack > item_size as f64 * 1.4 {
            score += (fleet_slack - item_size as f64 * 1.4).min(12.0) * 0.5;
