    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: perfect-closure cascade — leaving residual exactly equal to a
    // small next item, weighted by how late in the stream we are.
    if next_item_size > 0 && post_residual == next_item_size && post_residual <= twentieth {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // NEW: avoid creating residual that is just barely below next item
    // (near-miss strand), strongest mid-stream.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
