            score -= (avg_waste - this_waste) * 0.11 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: absolute dead-space ceiling — residuals below the next item AND
    // below 8% of capacity are almost surely wasted; punish harder late.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let frac = post_residual as f64 / cap;
        if frac < 0.08 {
            score += (0.08 - frac) * 60.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // NEW: reusable-residual steering — prefer leaving residuals that match
    // common small-item sizes (multiples of 5) over odd stranded values.
    if post_residual > 0 && post_residual % 5 == 0 && post_residual >= 5 {
        score -= 1.2 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "friendly" residue classes are more reusable later.
    let res = post_residual;
    let class = res % 10; // harmonic subclass of residual

    // Reward residuals that are multiples of common item-size harmonics.
    let friendly = |r: u32| -> f64 {
        let mut bonus = 0.0;
        if r % 10 == 0 { bonus += 6.0; }
        if r % 20 == 0 { bonus += 4.0; }
        if r % 25 == 0 { bonus += 3.0; }
        if r % 50 == 0 { bonus += 4.0; }
        bonus
    };
    score -= friendly(res);

    // Penalize awkward dead space: small but nonzero leftovers are hard to fill.
    if res > 0 && res < 10 {
        score += 12.0;
    } else if res >= 10 && res <= 19 {
        score += 3.0;
    }

    // Perfect fit is ideal.
    if res == 0 {
        score -= 100.0;
    }

    // Coupling with next item: reward if the next item fits the post residual
    // (chain packing), penalize near misses.
    if next_item_size > 0 {
        if next_item_size <= res {
            let slack = res - next_item_size;
            score -= 8.0 - (slack as f64).min(8.0);
            if slack == 0 { score -= 10.0; }
        } else {
            // next item cannot fit: leftover likely wasted
            score += ((next_item_size - res) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly so we only open when
    // existing bins are truly poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if current item is large relative to mean residual, opening
        // a fresh bin can be better.
        score -= (item_size as f64 / bin_capacity as f64) * 18.0;
    }

    // Prefer filling bins with lower residual among equals (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight early-stream preference to keep bins open and consolidated.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // Tie-break by harmonic class to make selection deterministic & structured.
    score += class as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 1.0 - progress;

    // Non-linear tightness reward on post_residual.
    let tight = 1.0 - (pr / cap);
    score -= 55.0 * tight * tight;

    // Dead-space bands with fine near-exact tiers (borrowed from best).
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < fortieth {
        score += 4.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual < twentieth {
        score += 10.0 + (twentieth - post_residual) as f64 * 0.04;
    } else if post_residual < tenth {
        score += 26.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 34.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score -= 8.0;
    }

    // Lookahead: reward exact and near-exact chains, penalize unusable slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0;
        } else if slack < cap * 0.1 {
            score -= 14.0;
        } else if slack < cap * 0.25 {
            score -= 6.0;
        } else {
            score -= slack * 0.15;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 20.0 + 5.0 * horizon;
        if post_residual < fifth {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: discourage spreading when many bins are open.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += 8.0 * crowding * (pr / cap);

    // Time horizon: greedier about tight fits later.
    score -= 18.0 * progress * tight;

    // Mean-residual deviation: prefer bins with below-average residual.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.08;
    } else {
        score += (-dev) * 0.02;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score += 50.0; // base penalty: prefer existing bins
        score -= 65.0 * big_item * big_item;
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 12.0;
        }
        if fitting_bins_count <= 1 {
            score -= 38.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 9.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 12.0;
        }
        if fitting_bins_count >= 3 {
            score += 3.0 + fitting_bins_count as f64 * 0.5;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        let fresh_left = cap - item_size as f64;
        if fresh_left % 10.0 == 0.0 {
            score -= 2.0;
        }
        if next_item_size > 0 && bin_capacity.saturating_sub(item_size) < next_item_size
            && mean_residual >= next_item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        score += 5.0 + 4.0 * horizon;
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.3;
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 18.0;
        } else if chain_slack <= twentieth {
            score -= 11.0;
        } else if chain_slack <= tenth {
            score -= 8.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 7.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let mut waste = waste_ratio * waste_ratio * 11.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        score += waste;
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.09 * horizon;
        } else {
            score += (pr - mean_residual) * 0.05 * horizon;
        }
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 5.0 * horizon;
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.22;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (< 10, min item size) are pure waste: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Slightly larger gaps that few future items can use are also risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // --- Reward tight fits ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit: exact closure of the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Last-chance pressure ---
    // If this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine for large items or when nothing fits well,
        // but penalize it when an existing bin gives a tight fit.
        score += 10.0 * fill_ratio;
        // Slight bias toward consolidating into existing bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
        // If the next item would also fit the fresh bin, a new bin is attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // --- Open-bin pressure ---
    // Many open bins: prefer placements that reduce bin count pressure (tight fits),
    // and penalize spreading into already-crowded sets with large mean residual.
    if open_bins_count > 0 {
        let mean_gap = (mean_residual - post_residual as f64).abs();
        score += 0.05 * mean_gap;
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * fill_ratio;
    }

    // --- Lookahead: avoid blocking the next item ---
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover space can't hold the next item: mild dead-space penalty scaled by gap size.
        score += 0.4 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual can still serve the next item: reward.
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
