        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount + quadratic strand penalty.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: bonus if the next item exactly fills post-residual.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 18.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gap
            score += 4.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, favor opening fresh bins less (pack tighter);
    // late in stream, mild consolidation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * fill * t;

    // Compare against mean residual: bins below mean residual are scarcer, favor them.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make it attractive only when current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + fitting_bins_count as f64);
        score = 40.0 + 60.0 * (1.0 - crowding.clamp(0.0, 1.0)) - 15.0 * pressure.min(3.0);
        // late in stream, prefer reusing open bins
        score += 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;
    let pr = post_residual as f64;

    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;

    // Near-perfect fill tiers (borrowed, retuned).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual < fortieth {
        score -= 220.0 + (fortieth - post_residual) as f64 * 0.5;
    } else if post_residual < twentieth {
        score -= 120.0;
    } else if post_residual < tenth {
        score -= 40.0 + (tenth - post_residual) as f64 * 0.05;
    }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 320.0;
        } else if slack < cap * 0.1 {
            score -= 90.0;
        } else if slack < cap * 0.25 {
            score -= 45.0;
        } else {
            score -= 60.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item does NOT fit: penalize blocking gap, horizon-weighted.
        let gap = (next_item_size - post_residual) as f64;
        score += (8.0 + 30.0 * (gap / 100.0).min(1.0)) * (0.5 + 0.5 * (1.0 - progress));
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.07;
    } else {
        score -= (-dev) * 0.03;
    }

    // Last-chance bin: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 160.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.5;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        score += 60.0 * (1.0 - open_pressure) + 10.0 * progress;
        if item_size >= 60 {
            score -= 90.0;
        }
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth {
            score += 5.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        if next_item_size > 0 && fresh_left2 < next_item_size && mean_residual >= next_item_size as f64 {
            score += 4.0;
        }
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (pr - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.09 * (1.0 - progress);
        } else {
            score += (pr - mean_residual) * 0.05 * (1.0 - progress);
        }
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.06 * (1.0 - progress);
        }
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) - norm_post * progress * progress;

    // Smoothly increasing penalty for waste as stream progresses.
    let mut score = post * (1.0 + 0.5 * progress) + 20.0 * poly;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 15.0 * tightness * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: penalize bins whose post-residual can't fit the next item.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 10.0 + 15.0 * progress;
        } else {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Mild preference for consolidating into fewer bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balance).
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: penalize slightly unless post_residual is attractive.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 1.0 - progress;
    let mut score = pr;

    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;

    // Dead-space bands (borrowed tiering, tuned).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < twentieth {
        score += 10.0 + (twentieth - post_residual) as f64 * 0.05;
    } else if post_residual < tenth {
        score += 26.0 + (tenth - post_residual) as f64 * 0.06;
    } else if post_residual < fifth {
        score += 30.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 3.0;
    } else if pr <= cap * 0.5 {
        score -= 4.0;
    } else {
        score -= 9.0;
    }

    // Tight-fit reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 12.0 * fit_ratio * fit_ratio;
    }

    // Lookahead: next item fits -> reward by slack; else penalize stranded residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0;
        } else if slack < cap * 0.1 {
            score -= 14.0;
        } else if slack < cap * 0.25 {
            score -= 6.0;
        } else {
            score -= slack * 0.15;
        }
        // Two-item chain.
        let two = item_size + 2 * next_item_size;
        if two <= bin_residual {
            let s2 = bin_residual - two;
            if s2 == 0 { score -= 8.0; } else if s2 <= tenth { score -= 4.0; }
        }
    } else if next_item_size > 0 {
        if post_residual >= fifth {
            score += 8.0 + 3.0 * horizon;
        } else {
            score += 3.0 + 5.0 * horizon + (open_bins_count as f64).min(20.0) * 0.2;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mean-residual deviation: prefer below-mean waste.
    let dev = bin_residual as f64 - mean_residual;
    if bin_residual != bin_capacity {
        if dev > 0.0 { score -= dev * 0.07 * horizon; } else { score += (-dev) * 0.03; }
    }

    // Waste-forecast quadratic/cubic pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let wr = pr / cap;
        let mut waste = wr * wr * 12.0 * horizon + wr * wr * wr * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size { waste *= 0.5; }
        score += waste;
    }

    // Sprawl control: many open bins -> push consolidation.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
    }

    // Late-stream closing.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // New-bin candidate.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score = 120.0 - 60.0 * large - 30.0 * horizon;
        if fitting_bins_count == 0 {
            score -= 35.0;
        } else if fitting_bins_count >= 3 {
            score += 5.0 + fitting_bins_count as f64 * 0.6;
        }
        // Poor fits available -> new bin more attractive.
        if fitting_bins_count > 0 && fit_ratio < 0.5 {
            score -= 22.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
            if post_residual >= next_item_size { score -= 10.0; }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 4.0;
        }
        if item_size <= tenth {
            score += 5.0;
        }
    }

    // Divisibility nudges.
    if post_residual % 10 == 0 && post_residual > 0 { score -= 2.5; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction buckets (1/4, 1/2, 3/4)
    let q = post_residual as f64 / bin_capacity as f64;
    if q < 0.05 {
        score -= 60.0; // near-perfect fit: excellent
    } else if q < 0.25 {
        score += 12.0; // small dead space: mildly bad
    } else if q < 0.50 {
        score += 25.0; // half-ish leftover: bad unless reusable
    } else {
        score -= 8.0; // large leftover: bin stays flexible
    }

    // Modulo-10 arithmetic: residuals divisible by 10 pair well with typical item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead harmony: can next item exactly fill post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            if frac > 0.8 {
                score -= 30.0;
            } else if frac > 0.5 {
                score -= 12.0;
            } else {
                score += 6.0; // next item too small to exploit this residual well
            }
        } else {
            // next item cannot fit here; penalize more if residual is in dead zone
            if q > 0.05 && q < 0.25 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: prefer consolidation (tighter fits)
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 4.0 * (1.0 - q);
    }

    // Early stream: keep bins roomy; late stream: prefer tight packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Mean residual coupling: if this bin is much tighter than average, favor it
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual >= bin_capacity);
        if desperate {
            score -= 35.0;
        } else {
            score += 50.0; // discourage wasting a fresh bin on a mediocre fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
