    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: dead-space harmonic target — reward residuals that divide the
    // remaining stream horizon, steering toward perfectly packable leftovers.
    if post_residual > 0 && item_size > 0 && post_residual % item_size == 0
        && post_residual != bin_capacity {
        score -= 2.0 + 2.0 * (1.0 - progress);
    }

    // NEW: cross-bin complement probe — if the post-residual plus next item
    // matches a typical fleet residual scale, prefer tighter closure here.
    if next_item_size > 0 && post_residual > next_item_size
        && bin_residual != bin_capacity {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) < mean_residual * 0.5 {
            score -= 1.5;
        } else if (after as f64) > mean_residual * 1.5 {
            score += 1.5;
        }
    }

    score
}

