    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // MUTATION: tighter new-bin gate — require fresh bin to beat best open fit by margin
    // proportional to how many open bins can already hold the item.
    if bin_residual == bin_capacity && fitting_bins_count >= 1 {
        let pressure = (fitting_bins_count as f64 / 4.0).min(2.0);
        score += 8.0 * pressure;
    }

    // MUTATION: strong exact-closure of current bin via item (bin_residual == item_size).
    if bin_residual != bin_capacity && bin_residual == item_size {
        score -= 10.0;
    }

    // MUTATION: penalize leaving residuals that no typical next item can use
    // (residual below smallest plausible item band) more aggressively late.
    if post_residual > 0 && post_residual < fortieth && progress > 0.5 {
        score += 6.0 * (progress - 0.5);
    }

    // MUTATION: reward splitting residuals that match next_item exactly across chain,
    // discourage consuming a bin whose leftover would strand next_item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && (next_item_size - post_residual) <= 2 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space (min item size ~1..100, small gaps trap capacity)
    }
    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward tight fits relative to capacity.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }
    // Many open bins: pressure to fill existing bins rather than open new ones.
    score += 8.0 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin late in stream when mean residual is large (fragmented state).
        if mean_residual > 40.0 {
            score -= 90.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 70.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty for blocking.
        score += 15.0;
    }

    // Stream progression: early on, be pickier about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = pr;

    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;

    // Perfect / near-perfect closure tiers.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual < fortieth {
        score -= 40.0;
    } else if post_residual < tenth {
        score -= 12.0;
    } else if post_residual < fifth {
        score += 6.0;
    } else if post_residual <= third {
        score += 3.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.0;
    } else {
        score -= 6.0;
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    // Lookahead: next item fits here.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 500.0;
        } else if slack < cap * 0.1 {
            score -= 60.0;
        } else if slack < cap * 0.25 {
            score -= 25.0;
        } else {
            score -= slack * 0.17;
        }
        // triple-chain probe
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item does not fit: penalize blocking gap, worse early.
        let gap = (next_item_size - post_residual) as f64;
        score += 4.0 + gap.min(cap) * 0.06 * (1.5 - progress);
