        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 60.0;
        } else if chain_slack <= twentieth {
            score -= 20.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space ratio: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Strand-ratio discount: tiny residue relative to item = strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Dead-space delta vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.09 * (1.0 - progress);
        } else {
            score += (pr - mean_residual) * 0.05 * (1.0 - progress);
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (pr - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Large-item rescue: nearly closed bin hosting a big item.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but don't leave dead space
    // that can't hold the next item.

    // Lookahead: reward exact/near match between post_residual and next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as i64 == next_item_size as i64 {
            // Perfect two-item fill: this bin becomes exactly full after next item.
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: strong reward, scaled by closeness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: dead space penalty relative to leftover size.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins with residuals near the mean are
    // "typical"; placing into a much-larger-than-mean residual is cheap,
    // placing into a small residual risks fragmentation.
    if post_residual as f64 > mean_residual {
        score -= 1.5 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 1.5 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item fits
    // very poorly everywhere (handled by rewards above). A fresh bin has
    // large post_residual, so a mild extra penalty keeps it as fallback.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But if the next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: slightly prefer already-open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 2.0 * progress;
    }

    score
}

