            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: dead-space ratio refinement — penalize residual just below the next
    // item's size by a small margin (near-miss trap), scaled by horizon.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= cap * 0.05 {
            score += miss / (cap * 0.05) * 3.0 * (1.0 - progress);
        }
    }

    // NEW: reward bins whose post residual can absorb the next item twice
    // (chain continuation keeps space productive).
    if next_item_size > 0 && next_item_size > 0
        && post_residual >= 2 * next_item_size && bin_residual != bin_capacity {
        score -= 2.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
