        } else {
            score += (this_waste - avg_waste) * 0.06 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: dead-space elimination sweep — if the leftover after placement is
    // small relative to capacity AND the fleet has plenty of residual slack,
    // reward absorbing it now rather than leaving a sliver behind.
    if bin_residual != bin_capacity && post_residual > 0 && post_residual <= fortieth {
        let fleet_slack = open_bins_count as f64 * mean_residual;
        if fleet_slack > item_size as f64 {
            score -= 3.0 + (fortieth - post_residual) as f64 * 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 0.9 * (pr / cap).powi(2) * cap + 0.4 * (pr / cap).powi(3) * cap;

    // Smooth stream-progress coupling: later in the stream, tighten more
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Reward tight fits relative to bin residual (fraction filled now)
    let fill_frac = item_size as f64 / r.max(1.0);
    score -= 6.0 * fill_frac * fill_frac;

    // Penalize bins far from mean residual (fragmentation pressure)
    score += 0.15 * (r - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 4.0 * (1.0 - slack / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space mildly, more as stream progresses
        score += 2.0 * (pr / cap) * (0.5 + progress);
    }

    // New-bin candidate: make it unattractive unless open bins are very fragmented
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress - 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

