        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW mutation: best-fit exclusivity bonus — when this bin's post-residual
    // is the tightest possible fit class and few bins compete, reward closure
    // to reduce residual variance (diagnosed weakness: dead space ratio).
    if bin_residual != bin_capacity && post_residual > 0 && post_residual <= twentieth
        && fitting_bins_count <= 2 {
        score -= 4.0 + 2.0 * (1.0 - progress);
    }

    // NEW mutation: fleet-wide dead-space pressure — when mean residual is high
    // (many bins stranded), tighten selection toward the bin whose post-residual
    // is most likely to be consumed by the next item, and slightly prefer
    // opening a fresh bin over deepening an over-fragmented fleet.
    if mean_residual > cap * 0.3 && bin_residual != bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (mean_residual / cap);
        } else {
            score += 2.0 * (mean_residual / cap);
        }
    }

    // NEW mutation: new-bin gate refinement — open a fresh bin only when no
    // open bin can host both the item and the next item tightly, otherwise
    // keep the fleet compact.
    if bin_residual == bin_capacity && fitting_bins_count >= 1 && next_item_size > 0 {
        let any_chain = item_size + next_item_size <= bin_capacity;
        if any_chain && item_size as f64 <= cap * 0.4 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space
    // in terms of common item-size classes (divisors / multiples of capacity fractions).
    // Residuals that align with common size classes are more likely to be filled later,
    // so we reward them (subtract), while awkward residuals are penalized (add).

    let post = post_residual;
    if post > 0 {
        // Class A: residual exactly divisible by common small sizes -> very fillable
        if post % 10 == 0 {
            score -= 6.0;
        } else if post % 5 == 0 {
            score -= 3.0;
        }
        // Class B: residual fits common capacity fractions (25/33/50)
        if post == bin_capacity / 2 {
            score -= 8.0;
        } else if post == bin_capacity / 4 || post == bin_capacity / 3 {
            score -= 5.0;
        }
        // Class C: tiny dead space is nearly unusable -> heavy penalty
        if post < 10 {
            score += 12.0;
        } else if post < 20 {
            score += 5.0;
        }
        // Class D: awkward middle band (just above typical small items) is a trap
        if post > 10 && post < 25 && post % 10 != 0 {
            score += 4.0;
        }
    }

    // Lookahead coupling: if the next item fits the post residual, this placement
    // creates a perfect pair -> reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
        // Perfect exact pairing is ideal
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits this bin now but our placement would break that -> penalty
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how crowded existing bins are.
        score += 18.0 + 0.5 * open_bins_count as f64;
        // If open bins are mostly full (low mean residual), a new bin is reasonable.
        if mean_residual < 0.25 * cap {
            score -= 10.0;
        }
        // Large items early in the stream benefit from a fresh bin.
        if item_size > bin_capacity * 3 / 4 {
            score -= 8.0;
        }
    } else {
        // Reward filling existing bins proportionally to how well the item fits.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 5.0 * fill_ratio;
        // Perfect fit (zero waste) is always excellent.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Stream progression: early on, prefer consolidating into few bins;
    // later, allow more tolerance for opening bins when fragmentation is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count as f64 > 4.0 + 10.0 * progress {
        score += 3.0; // too many open bins: discourage adding another
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 40.0;
        if next_item_size > 0 && item_size <= tenth {
            score -= 4.0;
        }
    }

    // Fine-grained dead-space bands (from best heuristic)
    if post_residual > 0 && (post_residual as f64) < 12.0 {
        score += 30.0 + (12.0 - pr) * 0.05;
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }
    if post_residual > 0 && post_residual < fortieth {
        score += 6.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual > 0 && post_residual < twentieth {
        score += 12.0 + (twentieth - post_residual) as f64 * 0.04;
    }

    // Harmonic residual bands
    if post_residual > 0 && post_residual < fifth {
        score += 38.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.5;
    } else {
        score -= 8.0;
    }

    // Divisibility rewards
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Open bins pressure
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 17.0;
    }
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.5;
    }

    // Lookahead with graded slack reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 32.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 8.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 5.0; }
    } else {
        score += pr * 0.5;
    }

    // Two-item lookahead chain
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 17.0 + 11.0 * progress;
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.6;
        }
        let open_cap = open_bins_count as f64 * mean_residual;
        if open_cap > item_size as f64 * 2.0 {
            score += 3.0;
        }
        // Fresh-bin exact-fill probes (from best)
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // Sprawl guard against needless new bins
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        // Low fleet residual -> prefer reuse
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5
            && mean_residual < cap * 0.12 {
            score -= 5.0;
        }
    }

    // Mean-residual coupling
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    // Decimal alignment
    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.2;
    }

    // Waste-forecast
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        score += 5.0 + 5.0 * (1.0 - progress);
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Global sprawl control
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.14;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening
    if step_index + 4 >= total_items {
        score += pr * 0.35;
    }

    // Size-matched pairing bonus
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Multi-fit dilution
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Dead-space ratio: quadratic + cubic waste pressure (from best)
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Horizon-weighted fill-pressure
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Dead-space delta vs fleet average
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        if pr < avg_waste {
            score -= (avg_waste - pr) * 0.09 * (1.0 - progress);
        } else {
            score += (pr - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Strand-ratio discount
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.06 * (1.0 - progress);
        }
    }

    // Residual-entropy steering
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Exact-fill sweep
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Triple-chain probe
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Residual-floor guard
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Adaptive tightness
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Progression: tighten packing as stream advances
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that cannot plausibly
    // fit a future item is pure waste, so penalize it hard.
    let min_item = 1u32;
    let gap_threshold = if next_item_size > 0 { next_item_size.max(min_item) } else { min_item };
    if post_residual > 0 && post_residual < gap_threshold {
        // Dead space: gap too small even for the lookahead item.
        let dead = (gap_threshold - post_residual) as f64;
        score += 40.0 + 3.0 * dead;
    }
    // Absolute dead zone: gap below the smallest conceivable item (1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Perfect fit reward: subtract to strongly prefer filling a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit bonus: residual mostly consumed, small usable remainder.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when
    // residuals are still large; encourage consolidation.
    let avg_usable = mean_residual / open_bins_count.max(1) as f64;
    if avg_usable < 30.0 {
        score += 20.0; // bins are mostly full; avoid fragmenting leftovers
    } else {
        score -= 5.0;  // plenty of slack; consolidation is cheap
    }

    // Last-chance bonus: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit; make the empty bin costly by
    // default but cheaper as the stream progresses and pressure mounts.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 20.0 * progress;
        // If the item would leave a large awkward remainder in any bin,
        // a fresh bin is fine — soften the penalty.
        if post_residual >= 40 {
            score -= 25.0;
        }
    }

    // Lookahead synergy: reward bins whose post_residual still accommodates
    // the next item (keeps chains going), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
