        }
        if next_item_size > 0 {
            let fresh_left3 = bin_capacity.saturating_sub(item_size);
            if fresh_left3 < next_item_size && mean_residual >= next_item_size as f64 {
                score += 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // NEW: avoid opening a fresh bin when the fleet already holds enough
        // aggregate residual to absorb the item with tight leftover.
        let fleet_res = open_bins_count as f64 * mean_residual;
        if fleet_res >= item_size as f64 {
            let over = fleet_res - item_size as f64;
            score += 2.0 + (over / cap).min(1.5) * 4.0 * horizon;
