            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // New: prefer opening fresh bins whose leftover is a multiple of small items.
        if next_item_size > 0 && fresh_left2 >= next_item_size && fresh_left2 % next_item_size == 0 {
            score -= 3.0;
        }
    }

    // Mean-residual deviation.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure (retuned).
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.5 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.10 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: harvestable-orphan penalty — residuals that no plausible future item
    // can use should steer the packer away from creating them, weighted by how
    // many open bins already hold similar stranded space.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = (post_residual as f64 / cap) * (1.0 - progress);
        let crowd = (open_bins_count as f64).min(15.0) / 15.0;
        score += 3.5 * stranded * (0.5 + crowd);
    }

    // NEW: multi-fit preference — when several bins fit, favor the one whose
    // post-residual best matches the fleet mean (keeps a homogeneous pool).
    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap).min(1.0);
        score -= 1.5 * match_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Smooth non-linear coupling of post-residual with stream progress.
    let mut score = pr as f64;
    score += 40.0 * base * base * (1.0 - progress);
    score -= 25.0 * base * (1.0 - base) * progress;

    // Tight-fit reward: smooth bell around near-perfect packing.
    let tightness = 1.0 - (item_size as f64 / bin_residual as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Last-chance bin: smooth urgency term.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: reward residual that still fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 12.0 * (nxt - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (fragmentation smoothing).
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make it less attractive unless existing bins are bad fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;

    // Perfect / near-perfect fill rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < fortieth {
        score -= 200.0;
    }

    // Lookahead: next item fits exactly or nearly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 30.0;
            } else if slack < cap * 0.1 {
                score -= 15.0;
            } else if slack < cap * 0.25 {
                score -= 7.0;
            } else {
                score -= slack * 0.17;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 * (gap / 100.0).min(1.0);
        }
    }

    // Two-item chain lookahead.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 16.0;
    }

    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        score += 17.0 + 10.0 * progress + 60.0 * (1.0 - open_pressure);
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size + next_item_size);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 {
            score -= 2.0;
            if fresh_left2 <= twentieth {
                score -= 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        // Sprawl control: too many open bins relative to progress.
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        // If mean residual already large, prefer reusing it instead of a fresh bin.
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5 {
            if mean_residual < cap * 0.12 {
                score -= 5.0;
            }
        }
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Strand-ratio discount.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.06 * (1.0 - progress);
        }
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let this_waste = pr;
        if this_waste < mean_residual {
            score -= (mean_residual - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - mean_residual) * 0.05 * (1.0 - progress);
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Residual-entropy banding: residual close to mean is reusable.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (pr - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual != bin_capacity
        && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
