    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Strand-ratio discount.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let this_waste = post_residual as f64;
        if this_waste < mean_residual {
            score -= (mean_residual - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - mean_residual) * 0.05 * (1.0 - progress);
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (items are 10..80, capacity 100)
    let residue = (post_residual % 10) as f64;
    // Bins whose residual is a "harmonic" fraction of capacity (25/50/75/100) are reusable
    let harmonic = post_residual % 25 == 0;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if harmonic {
        score -= 30.0; // residual aligns with quarter-capacity classes
    } else {
        // Penalize awkward residues: dead space that no typical item can fill
        score += residue * 3.0;
    }

    // Integer-division class: how many "average items" fit in the leftover
    let avg_item = 45.0f64;
    let fits_count = (post_residual as f64 / avg_item).floor();
    if fits_count == 0.0 && post_residual > 0 {
        score += 40.0; // dead space: too small for even the smallest item class
    }

    // Lookahead coupling: if next item fits into the post-residual class, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5; // tighter next-fit = better
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0; // chain preserves harmonic alignment
            }
        } else {
            // next item won't fit here; penalize more if this bin was our only option
            if fitting_bins_count <= 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only one bin can fit the item -> use it rather than open new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins exist
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; make it slightly worse than a decent existing fit
        score += 120.0 + open_bins_count as f64 * 2.0;
        // But if existing bins are all badly fragmented, opening fresh is fine
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 100.0;
        }
        // Early stream: prefer accumulating open bins slightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild fragmentation pressure: prefer filling bins far below mean residual
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Small tightness term: quadratic penalty on leftover keeps packing tight
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Capacity-relative dead-space bands with fine near-exact tiers.
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 36.0;
    } else if post_residual < fortieth {
        score += 6.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual < twentieth {
        score += 12.0 + (twentieth - post_residual) as f64 * 0.04;
    } else if post_residual < tenth {
        score += 30.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 38.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score -= 8.0;
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 32.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Last-chance bin: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 17.0 + 10.0 * progress;
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        if item_size as f64 > cap * 0.85 && fitting_bins_count == 0 {
            score -= 6.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5 {
            if mean_residual < cap * 0.12 {
                score -= 5.0;
            }
        }
        if next_item_size > 0 {
            let fresh_left3 = bin_capacity.saturating_sub(item_size);
            if fresh_left3 < next_item_size && mean_residual >= next_item_size as f64 {
                score += 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
    }

    // Mean-residual deviation.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure (refined horizon weighting).
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 12.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 5.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.0 + reach / cap * 4.0);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.09 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.05 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.06 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // NEW: dead-space ratio refinement — penalize residuals that are too large to
    // ever be closed by typical remaining items, scaled by remaining horizon.
    if bin_residual != bin_capacity && post_residual > 0 {
        let ratio = pr / cap;
        let horizon = 1.0 - progress;
        if next_item_size > 0 && post_residual < next_item_size {
            // Unusable for the immediate next item: escalate with horizon.
            score += ratio * 18.0 * horizon;
        }
        // Very large residual after placement signals a wasted slot; push toward
        // bins whose post-residual stays in the closable mid-band instead.
        if ratio > 0.5 && post_residual <= third {
            score += 6.0 * (ratio - 0.5);
        }
    }

    // NEW: fleet-level compaction pressure — when the fleet is running hot
    // (many open bins relative to progress), reward leaving tight residuals.
    if bin_residual != bin_capacity && open_bins_count as f64 > 0.45 * (progress * total_items.max(1) as f64 + 1.0) {
        if post_residual > 0 && post_residual <= twentieth {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // NEW: perfect-pair shaping — if the residual after placement equals the next
    // item exactly at any horizon, this is a guaranteed future closure.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward (subtract) when bin is filled exactly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: gaps too small to hold anything useful are wasted.
        // Treat gaps below ~10 as near-unusable; scale penalty quadratically
        // as the gap shrinks toward zero (but is not zero).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * (10.0 - pr) * 8.0;
        } else if pr > 50.0 {
            // Large leftover is fine only if the bin was fresh; penalize
            // fragmenting a big residual with a small item mildly.
            score += (pr - 50.0) * 0.5;
        }

        // If the next item could exactly use this post_residual, reward heavily.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item cannot fit in the leftover: leftover is likely dead space.
            score += (post_residual as f64) * 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 3.0 * (0.5 + progress);

    // New-bin candidate: only attractive when this bin is fresh (residual == capacity)
    // and existing residuals are all too fragmented relative to the item.
    if bin_residual == bin_capacity {
        // Mild default penalty so we prefer filling existing bins unless fit is bad.
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: must open a new one
        } else if post_residual as f64 > mean_residual {
            // Fresh bin leaves more room than average open bin; slightly better.
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (balanced packing).
    score -= (bin_residual as f64 - mean_residual).abs() * -0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
