    // too small for the next item; those are the costliest near-misses.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= tenth as f64 {
            score -= miss * 0.35 * (1.0 - progress);
        }
    }

    // NEW: fleet-wide fill coordination — when mean residual is very low
    // (fleet nearly full), tighten preference for the emptiest-fitting bin.
    if bin_residual != bin_capacity && mean_residual < cap * 0.08 && open_bins_count > 3 {
        score -= (cap * 0.08 - mean_residual) * 0.6;
    }

    // NEW: large-residual conservation — bins with big residuals are precious
    // late in the stream; discourage spending them on tiny items.
    if bin_residual != bin_capacity && bin_residual > bin_capacity / 2
        && item_size <= twentieth && progress > 0.4 {
        score += 3.5 * progress;
    }

    score
}

