        let chain_depth = post_residual / next_item_size;
        if chain_depth >= 2 {
            let depth_bonus = (chain_depth as f64).min(4.0);
            score -= depth_bonus * (1.5 + 1.5 * (1.0 - progress));
        }
    }

    score
}

