        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        score += waste;
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.5 + reach / cap * 4.5);
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (pr - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let this_waste = pr;
        if this_waste < mean_residual {
            score -= (mean_residual - this_waste) * 0.10 * (1.0 - progress);
        } else {
            score += (this_waste - mean_residual) * 0.06 * (1.0 - progress);
        }
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.07 * (1.0 - progress);
        }
    }

    // Dead-space floor trap.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
        let dead_ratio = pr / next_item_size as f64;
        score += 3.0 * (1.0 - dead_ratio) * (0.5 + density.min(1.0));
    }

    // Perfect-split preference.
    if post_residual > 0 && post_residual * 2 == bin_residual && next_item_size > 0
        && next_item_size <= post_residual {
        score -= 3.5;
    }

    // Residual absorption check.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = pr - next_item_size as f64;
        if fit_margin > 0.0 && fit_margin < mean_residual * 0.5 {
            score += fit_margin * 0.12;
        }
    }

    // Harvest pressure: reward near-emptied bins.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = pr / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // NEW mutation: waste-anticipation — when the post-fit residual cannot
    // hold the next item but the fleet mean could, escalate the penalty
    // proportionally to how much better the fleet average is.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && mean_residual >= next_item_size as f64 {
        score += (mean_residual - pr) * 0.15;
    }

    // NEW mutation: chain-closure bonus — placing the item so that the next
    // item closes the bin exactly is highly compacting, especially early.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 - progress);
    }

    // NEW mutation: avoid leaving residuals in the awkward 1..=5 sliver zone
    // which almost no item can use; penalize proportional to closeness to 1.
    if post_residual > 0 && post_residual <= 5 {
        score += 2.0 + (6 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = pr;

    // Perfect / near-perfect fill tiers (capacity-relative).
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual < fortieth {
        score -= 250.0;
    } else if post_residual < twentieth {
        score -= 120.0;
    } else if post_residual < tenth {
        score -= 40.0;
    }

    // Lookahead: reward next-item fit tightly, penalize blocking gaps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 130.0 * (1.0 - slack / cap);
            // two-item chain probe
            if 2 * next_item_size <= post_residual {
                score -= 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 45.0 * (gap / 100.0).min(1.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average, asymmetric.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.07;
    } else {
        score += dev * 0.02;
    }

    // Last-chance bin: strongly favor the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 160.0;
    }

    // Scarcity: fewer fitting bins -> keep using open ones.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.45;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        score += 55.0 * (1.0 - open_pressure) + 12.0 * progress;

        // Big items pair well with a fresh bin.
        if item_size as f64 > cap * 0.7 {
            score -= 85.0;
        }
        // Fresh bin whose leftover exactly fits next item is excellent.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size);
            if fresh_left == next_item_size {
                score -= 60.0;
            } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                let pair_left = bin_capacity - item_size - next_item_size;
                if pair_left == 0 {
                    score -= 45.0;
                } else if pair_left <= twentieth {
                    score -= 18.0;
                }
            }
        }
        // Avoid sprawl when fleet slack can absorb the item.
        let usable_slack = fitting_bins_count as f64 * mean_residual;
        if usable_slack > item_size as f64 * 1.5 {
            score += 8.0 + (usable_slack / item_size.max(1) as f64).min(3.0) * 3.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.6;
        }
        if mean_residual >= item_size as f64 && fitting_bins_count >= 1 {
            score += 10.0;
        }
        // Small items into fresh bins waste capacity.
        if item_size <= tenth {
            score += 12.0;
        }
    }

    // Waste-forecast: unusable residual is near-certain loss; stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let horizon = 1.0 - progress;
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += (4.0 + 5.0 * horizon) * (1.0 - dead_ratio);
    }

    // Dead-space quadratic/cubic pressure, mid-stream boost.
    if post_residual > 0 && bin_residual != bin_capacity {
        let wr = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = wr * wr * 14.0 * horizon + wr * wr * wr * 7.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        score += waste;
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.35;
    }

    // Complement pairing: leftover after placing item nearly closes bin.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth && bin_residual != bin_capacity {
        score -= 6.0;
    } else if complement > 0 && complement <= tenth && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Exact-fill sweep with the next item.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // Fragmentation index: many open bins with blocked residue is bad.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.3;
    }

    // Harvest pressure: nearly emptying a bin keeps the fleet tidy.
    if bin_residual != bin_capacity && open_bins_count > 4 && post_residual > 0 {
        let tidy = pr / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 2.0; }
    if post_residual % 20 == 0 { score -= 1.5; }

    // Large-item urgency in open bins.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Dead-space delta vs fleet average, horizon-weighted.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.10 * (1.0 - progress);
        } else {
            score += (pr - mean_residual) * 0.06 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
