    }

    // Triple-chain probe
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Strand-ratio discount
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            let dead = (post_residual - next_item_size) as f64;
            score += dead * 0.07 * (1.0 - progress);
        }
    }

    // Progression: tighten packing as stream advances
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;

    // Dead-space penalty: small post_residual is bad (unusable sliver), large is waste.
    // Reward a "sweet spot" residual that still fits typical items (>= ~10-20% capacity).
    let sweet = (pr - 0.18) * (pr - 0.18);
    score += 60.0 * sweet * (0.5 + 0.5 * progress);

    // Polynomial coupling of post_residual with progress:
    // early in stream: prefer tight fills (minimize post_residual);
    // late in stream: tolerate larger residuals slightly to keep bins reusable.
    score += pr * (1.0 - 2.0 * progress + 1.5 * prog2 - prog3) * 20.0;

    // Perfect-fit bonus (smooth cubic falloff near zero residual)
    let tight_bonus = (-pr3 * 40.0).max(-40.0);
    score += tight_bonus;

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_score = 1.0 - gap / bin_capacity as f64;
        if fit_score > 0.0 {
            score -= 25.0 * fit_score * fit_score;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.3 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate (empty bin): penalize mildly, more so mid-stream,
    // so it is only chosen when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is below average (already partially filled well)
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    // Slight penalty for spreading across too many bins
    score += 0.1 * open_bins_count as f64 * pr;

    score
}

