        let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
        let dead_ratio = pr / next_item_size as f64;
        score += 3.0 * (1.0 - dead_ratio) * (0.5 + density.min(1.0));
    }

    // Harvest pressure: nearly emptying a bin keeps the fleet tidy
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = pr / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * horizon);
        }
    }

    // Residual absorption check
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = pr - next_item_size as f64;
        if fit_margin > 0.0 && fit_margin < mean_residual * 0.5 {
            score += fit_margin * 0.12;
        }
    }

    // Perfect-split preference
    if post_residual > 0 && post_residual * 2 == bin_residual && next_item_size > 0
        && next_item_size <= post_residual {
        score -= 3.5;
    }

    // Triple-chain probe
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Adaptive tightness
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Progression: tighten packing as stream advances
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit (zero or tiny residue) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 500.0;
    }

    // Class the residual into harmonic bands (1/4, 1/2, 3/4 of capacity)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let threeq = 3 * quarter;

    // Residue exactly on harmonic boundaries is more reusable
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Small residues (< quarter) are dead space: penalize proportionally harder
    if post_residual < quarter && post_residual > 0 {
        score += (quarter - post_residual) as f64 * 1.5;
    }

    // Mid-band residues (quarter..half) are decent; reward mildly
    if post_residual >= quarter && post_residual <= half {
        score -= 10.0;
    }

    // Large residues (> half) are fine, naturally low score already.

    // Lookahead coupling: does next item fit into the resulting residue?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's class pairs with residue
            score -= 25.0;
            // Extra reward if next item exactly fills residue (harmonic completion)
            if next_item_size == post_residual {
                score -= 100.0;
            }
            // Reward if next item leaves a harmonic-class residue again
            if (post_residual - next_item_size) % quarter == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit: residue likely wasted; penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
            // If gap is small (< 10), residue is nearly useful; soften penalty
            if gap < 10.0 {
                score -= gap * 0.3;
            }
        }
    } else {
        // Last item: any placement is fine; slight preference for tight fit
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // item is large relative to capacity or no bin fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 40.0;
        // Large items justify a fresh bin
        if item_size > 3 * bin_capacity / 4 {
            score -= 70.0;
        }
        // If many bins fit the item, prefer reusing one
        if fitting_bins_count > 2 {
            score += 30.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If mean residual is small, open bins are tight; new bin less costly
        if mean_residual < (item_size as f64) {
            score -= 25.0;
        }
    }

    // Modulo-class tiebreak on item_size vs residue (harmonic affinity)
    if item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Mild penalty when bin is much emptier than average (balance load)
    if (bin_residual as f64) > mean_residual + cap * 0.5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
