    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure (tuned upward mid-stream).
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        // MUTATION: escalate waste pressure when the residual cannot host the
        // next item and few alternatives exist — this targets the diagnosed
        // dead-space weakness directly.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
            waste *= 1.35;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure (slightly stronger).
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.5 + reach / cap * 4.5);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.10 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.06 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.07 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // Dead-space floor trap — residuals too small for the next item in
    // dense streams are near-certain waste; escalate with stream density.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += 3.0 * (1.0 - dead_ratio) * (0.5 + density.min(1.0));
    }

    // Perfect-split preference — balanced reuse for small items.
    if post_residual > 0 && post_residual * 2 == bin_residual && next_item_size > 0
        && next_item_size <= post_residual {
        score -= 3.5;
    }

    // Residual absorption check — prefer bins whose leftover can be
    // absorbed by the fleet's average residual neighborhood.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = post_residual as f64 - next_item_size as f64;
        if fit_margin > 0.0 && fit_margin < mean_residual * 0.5 {
            score += fit_margin * 0.12;
        }
    }

    // Harvest pressure — when many bins are open with small residuals,
    // reward using the bin that most nearly empties itself.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = post_residual as f64 / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION: dead-space differential — compare this bin's post-residual to
    // the best achievable among fitting bins; penalize leaving notably more
    // dead space than the fleet's tightest option, steering toward maximal
    // compaction rather than merely adequate fits.
    if bin_residual != bin_capacity && fitting_bins_count >= 2 && post_residual > 0 {
        let est_best = if mean_residual > 0.0 { mean_residual * 0.4 } else { cap * 0.1 };
        if pr > est_best {
            score += (pr - est_best) * 0.09 * (0.5 + progress * 0.5);
        }
    }

    // MUTATION: threshold-bridging bonus — when the item's placement brings
    // the residual just under a reusable divisibility landmark (50/100),
    // prefer it since such residuals pair cleanly with common item sizes.
    if post_residual > 0 && (post_residual == 50 || post_residual == 100
        || post_residual == 25 || post_residual == 75) {
        score -= 2.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tenth = bin_capacity / 10;
    let fifth = bin_capacity / 5;
    let twentieth = bin_capacity / 20;

    // Perfect and near-perfect closure.
    if post_residual == 0 {
        score -= 1000.0 * (1.0 - progress * 0.3);
    } else if post_residual < 10 {
        score -= 200.0;
    } else if post_residual <= twentieth {
        score -= 12.0 + (twentieth - post_residual) as f64 * 0.05;
    }

    // Lookahead: exact fit, tight fit, or blocking gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 * (1.0 - progress * 0.5);
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / cap);
            // two-item chain
            if 2 * next_item_size <= post_residual && post_residual < 3 * next_item_size {
                score += slack * 0.07 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
            score += 40.0 * (gap / 100.0).min(1.0) * (0.5 + density.min(1.0));
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.07;
    } else {
        score -= (-dev) * 0.02;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Scarcity discount among fitting bins.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.45;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        score += 60.0 * (1.0 - open_pressure) + 10.0 * progress;
        if item_size >= 60 {
            score -= 80.0;
        }
        // Pair completion in a fresh bin is excellent.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 25.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        // If fleet mean residual could absorb this item, avoid a new bin.
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 8.0;
        }
        // Usable fleet slack pressure.
        let usable_slack = fitting_bins_count as f64 * mean_residual;
        if usable_slack > item_size as f64 * 1.5 {
            score += 2.0 + (usable_slack / item_size.max(1) as f64).min(3.0) * 1.5;
        }
        // Small items should go into existing small gaps, not fresh bins.
        if item_size <= tenth && next_item_size > 0 {
            score += 6.0;
        }
    }

    // Waste-forecast: residual too small for the next item is near-certain waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Quadratic/cubic dead-space pressure, horizon-weighted.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.2;
        }
        score += waste;
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
    }

    // Harvest pressure: nearly emptying a bin keeps the fleet tidy.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = pr / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Dead-space delta vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.10 * (1.0 - progress);
        } else {
            score += (pr - mean_residual) * 0.06 * (1.0 - progress);
        }
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Horizon-weighted fill pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let reach = (post_residual - next_item_size) as f64;
        score -= (1.0 - progress) * (2.5 + reach / cap * 4.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1..=10) are pure waste; gaps that
    // cannot fit the lookahead item are also suspect.
    let min_gap = 10.0f64;
    if (post_residual as f64) < min_gap {
        score += 40.0; // dead space: nothing can ever fill it
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 12.0; // can't fit the known next item either
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (50.0 + 50.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 * (1.0 + bin_pressure);
    } else {
        score -= 8.0 * bin_pressure.min(2.0);
    }

    // Prefer bins whose residual is above the current mean (keep big gaps for
    // big future items, fill the tight bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild lookahead synergy: reward leaving a gap exactly fitting next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
