    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.5 + reach / cap * 4.5);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.10 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.06 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        // Quadratic strand penalty: residue fits next item once but not twice.
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.07 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // Dead-space floor trap — residuals too small for the next item are
    // near-certain waste; escalate with stream density.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += 3.0 * (1.0 - dead_ratio) * (0.5 + density.min(1.0));
    }

    // Perfect-split preference — balanced reuse for small items.
    if post_residual > 0 && post_residual * 2 == bin_residual && next_item_size > 0
        && next_item_size <= post_residual {
        score -= 3.5;
    }

    // Residual absorption check vs fleet residual neighborhood.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = post_residual as f64 - next_item_size as f64;
        if fit_margin > 0.0 && fit_margin < mean_residual * 0.5 {
            score += fit_margin * 0.12;
        }
    }

    // Harvest pressure — reward bins that nearly empty themselves.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = post_residual as f64 / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // NEW: dead-space minimization refinement — when the post-residual is
    // small but nonzero, scale the penalty by how unlikely any residual of
    // that size is to be filled later (small residuals are hard to reuse).
    if post_residual > 0 && bin_residual != bin_capacity {
        let tiny = post_residual as f64 / cap;
        if tiny > 0.0 && tiny < 0.03 {
            let scarcity_pressure = (0.03 - tiny) / 0.03;
            score += scarcity_pressure * 2.2 * (0.4 + 0.6 * progress);
        }
    }

    // NEW: residual-utility forecast — reward bins whose post-residual is a
    // near-exact multiple of likely small items (10/20/25 grid), which are
    // the most reusable gap shapes in integer streams.
    if post_residual > 0 && post_residual <= fifth && bin_residual != bin_capacity {
        let grid_hit = post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 10 == 0;
        if grid_hit {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // NEW: gap-consolidation pressure — prefer the fitting bin whose
    // post-residual is closest to the fleet mean, keeping residuals uniform
    // and predictable for future small-item absorption.
    if bin_residual != bin_capacity && post_residual > 0 && mean_residual > 0.0 {
        let uniformity = (post_residual as f64 - mean_residual).abs() / mean_residual;
        if uniformity < 0.15 {
            score -= (0.15 - uniformity) * 8.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.05;

    // Harmonic class of post_residual: bins whose residual falls into
    // "dead zones" (very small residuals that few items can use) are penalized
    // via modulo arithmetic on the capacity.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual > 0 {
        if post_residual < 10 {
            // residual too small for most items (min size 1..100 stream, but
            // small residual means near-perfect packing) -> reward
            score -= 6.0;
        } else if post_residual <= quarter {
            // awkward dead zone
            score += 4.0;
        } else if post_residual <= half {
            // mid zone: usable by many items
            score -= 2.0;
        }
    }

    // Modulo harmonic classes: residual divisible by common item sizes is more reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 3.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        }
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 10.0;
        } else if gap < 10 {
            score -= 5.0;
        } else {
            score -= (gap as f64).sqrt();
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this bin's leftover -> penalize slightly
        score += 2.0;
    }

    // Last-chance bin: only one fitting bin, avoid opening a new bin if fit is decent
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it
    // attractive only when existing bins would leave terrible residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its score is post_residual (= capacity),
        // so add a fixed penalty that tight fits in open bins can overcome.
        score += 8.0;
        // But if the item is huge relative to capacity, prefer a fresh bin
        // to avoid fragmentation of partially-filled bins.
        if item_size * 2 >= bin_capacity {
            score -= 12.0;
        }
        // Early in the stream, opening bins is cheap (many items to come that
        // can fill leftovers)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 4.0;
    }

    // Prefer bins with below-mean residual (fill the emptiest usable bins first)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(20.0) * 0.3;
    } else {
        score += (res - mean_residual).min(20.0) * 0.1;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Capacity-relative dead-space bands.
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 36.0;
    } else if post_residual < fortieth {
        score += 6.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual < twentieth {
        score += 12.0 + (twentieth - post_residual) as f64 * 0.04;
    } else if post_residual < tenth {
        score += 30.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 38.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score -= 8.0;
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 32.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
