    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tightly it packs the remainder
            let tightness = (post_residual - next_item_size) as f64;
            score -= 100.0 - tightness * 2.0;
