    // Penalize the brand-new empty bin candidate unless it enables a perfect
    // 2-item chain with the lookahead item.
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            (bin_capacity - item_size - next_item_size) as f64
