        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5 {
            if mean_residual < cap * 0.12 {
                score -= 5.0;
            }
        }
        if next_item_size > 0 {
            let fresh_left3 = bin_capacity.saturating_sub(item_size);
            if fresh_left3 < next_item_size && mean_residual >= next_item_size as f64 {
                score += 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 6.0;
        }
        let fleet_slack = open_bins_count as f64 * mean_residual;
        let usable_slack = fitting_bins_count as f64 * mean_residual;
        if usable_slack > item_size as f64 * 1.5 {
            score += 2.0 + (usable_slack / item_size.max(1) as f64).min(3.0) * 1.5;
        }
        if fleet_slack > cap * (open_bins_count as f64) * 0.35 && item_size as f64 <= cap * 0.4 {
            score += 2.5;
        }
        // NEW: refuse a fresh bin when the best existing post-fit residual
        // would be tighter than what a fresh bin leaves behind.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let fresh_waste = cap - item_size as f64;
            if mean_residual < fresh_waste * 0.55 {
                score += 3.0 + (fresh_waste * 0.55 - mean_residual).min(6.0);
            }
        }
    }

    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        // NEW: escalate waste pressure when the leftover is unusable by the
        // next item AND the fleet average residual is already small — such
        // gaps are pure dead space in dense streams.
        if next_item_size > 0 && post_residual < next_item_size
            && mean_residual < cap * 0.15 {
            waste *= 1.35;
        }
        score += waste;
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.5 + reach / cap * 4.5);
    }

    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.10 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.06 * (1.0 - progress);
        }
    }

    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.07 * (1.0 - progress);
            }
        }
    }

    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += 3.0 * (1.0 - dead_ratio) * (0.5 + density.min(1.0));
    }

    if post_residual > 0 && post_residual * 2 == bin_residual && next_item_size > 0
        && next_item_size <= post_residual {
        score -= 3.5;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = post_residual as f64 - next_item_size as f64;
        if fit_margin > 0.0 && fit_margin < mean_residual * 0.5 {
            score += fit_margin * 0.12;
        }
    }

    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = post_residual as f64 / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // NEW: residual-vs-next-item coupling — a leftover that exactly matches
    // the next item's size is a perfect handoff; reward it more as the
    // stream progresses (late-stream exactness is worth more).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 2.0 + 4.0 * progress;
    }

    // NEW: prefer bins whose post-fit residual stays a multiple of the next
    // item size, enabling multi-item chains in the same bin.
    if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0
        && post_residual >= next_item_size {
        let chainable = post_residual / next_item_size;
        score -= 1.5 * (chainable as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let base = norm_pr.powf(1.5 + 2.0 * progress);

    // Dead-space penalty: small post-residuals that can't fit typical items
    let dead = if pr > 0 { (cap / (pr as f64 + 1.0)).powi(2) } else { 0.0 };

    // Lookahead: reward if next item fits into post_residual
    let lookahead = if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        -2.5 * (next_item_size as f64 / cap)
    } else {
        1.5 * fit * progress
    };

    // Last-chance bonus: strongly prefer using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // Mild preference for tight fills relative to mean residual
    let mean_coupling = (mean_residual - pr) / cap * 0.5;

    // New-bin candidate: neutral-ish score so it's chosen only when fits are bad
    let new_bin_penalty = if bin_residual == bin_capacity {
        0.5 * cap + 10.0 * fit
    } else {
        0.0
    };

    let score = 40.0 * base + 0.05 * dead + lookahead + last_chance + mean_coupling + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue mod capacity quarters
    let quarter = bin_capacity / 4;
    let post_class = (post_residual / quarter) as f64;
    score -= post_class * 2.0; // reward bins whose leftover falls into a low harmonic band

    // Exact-fit harmonic: post_residual in small multiples of quarter is ideal
    if post_residual % quarter == 0 {
        score -= 6.0;
    } else {
        // penalize awkward residues, stronger for tiny unusable slivers
        let r = (post_residual % quarter) as f64;
        score += 3.0 * (r / quarter as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 12.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead harmonic: can next item land in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0; // chain exact fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic fit quality: slack near zero or near a quarter multiple is good
            if slack as u32 % quarter == 0 {
                score -= 5.0;
            }
            score -= 3.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // competition: normalize toward mean residual preference
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // New-bin candidate: only attractive when open bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin when mean residual is large (fragmented) or early stream with big items
        score -= fragmentation * 10.0 + progress * 2.0;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 4.0; // big next item favors fresh bin
        }
        if fitting_bins_count > 0 && mean_residual < 20.0 {
            score += 20.0; // open bins are tight, don't spread out
        }
    }

    // Mild preference for filling larger-residual bins when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Small tie-breaker on residual to break exact ties deterministically
    score += (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;

    // Perfect closure with progress-weighted reward.
    if post_residual == 0 {
        score -= 500.0 + 300.0 * progress;
    } else if post_residual < twentieth {
        score -= 120.0 * (1.0 - pr / twentieth as f64);
    } else if post_residual < tenth {
        score -= 40.0 * (1.0 - pr / tenth as f64);
    }

    // Lookahead: exact next-fit is gold; slack tiers otherwise.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0 * (1.0 - progress * 0.5);
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 250.0;
            } else if slack < cap * 0.1 {
                score -= 130.0;
            } else if slack < cap * 0.25 {
                score -= 60.0;
            } else {
                score -= 25.0;
            }
            // Chain: can the leftover host next item again?
            if post_residual >= 2 * next_item_size {
                score -= 20.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
            score += 30.0 * (gap / 100.0).min(1.0) * (0.6 + density.min(1.0));
        }
    }

    // Two-item chain closure.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 150.0;
        } else if chain_slack <= twentieth {
            score -= 70.0;
        } else if chain_slack <= tenth {
            score -= 35.0;
        }
    }

    // Relative-to-mean coupling: prefer tighter-than-average bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly favor to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 180.0;
    }

    // Scarcity: few fitting bins -> prefer open bins over fresh.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.5;
    }

    // New-bin candidate: open only when fleet slack can't absorb the item,
    // or the item is large and pairs perfectly with a fresh bin.
    if bin_residual == bin_capacity {
        let fleet_slack = fitting_bins_count as f64 * mean_residual;
        score += 70.0;
        if fleet_slack > item_size as f64 * 1.3 {
            score += 25.0 + ((fleet_slack / item_size.max(1) as f64).min(3.0)) * 6.0;
        }
        if item_size as f64 > cap * 0.7 {
            score -= 60.0;
        }
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size);
            if item_size + next_item_size == bin_capacity {
                score -= 90.0;
            } else if fresh_left >= next_item_size && fresh_left - next_item_size <= twentieth {
                score -= 40.0;
            } else if fresh_left < next_item_size && fresh_left < fifth {
                score += 20.0;
            }
        }
        if item_size <= tenth {
            score += 15.0;
        }
        if open_bins_count as f64 * 0.55 > progress * total_items.max(1) as f64 {
            score += 12.0;
        }
    }

    // Dead-space quadratic waste pressure, horizon-weighted.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 60.0 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 25.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.4;
        }
        score += waste;
    }

    // Dead-space floor trap: residual too small for next item is near-certain waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 25.0 + 30.0 * horizon;
    }

    // Late-stream tightening: minimize leftover aggressively at the end.
    if step_index + 5 >= total_items {
        score += pr * 0.4;
    }

    // Strand-ratio discount: tiny residue relative to item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand = pr / item_size.max(1) as f64;
        if strand < 0.15 {
            score -= (0.15 - strand) * item_size as f64 * 0.5;
        }
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 4.0; }
    if post_residual % 5 == 0 && post_residual > 0 { score -= 1.5; }

    // Harvest pressure: nearly-empty bins should be emptied when many are open.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = pr / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 3.0;
        }
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 8.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Capacity-relative dead space tiers with sharpened near-exact rewards.
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < fortieth {
        score += 6.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual < twentieth {
        score += 12.0 + (twentieth - post_residual) as f64 * 0.04;
    } else if post_residual < tenth {
        score += 30.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 38.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score -= 9.0;
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 34.0;
        } else if slack < cap * 0.08 {
            score -= 16.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Last-chance bin: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 17.0 + 10.0 * progress;
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        if item_size as f64 > cap * 0.85 && fitting_bins_count == 0 {
            score -= 6.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5 {
            if mean_residual < cap * 0.12 {
                score -= 5.0;
            }
        }
        if next_item_size > 0 {
            let fresh_left3 = bin_capacity.saturating_sub(item_size);
            if fresh_left3 < next_item_size && mean_residual >= next_item_size as f64 {
                score += 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // Penalize opening a bin when fleet mean residual could absorb the item.
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 6.0;
        }
        // Open-bin avoidance scales with how much usable slack exists in the fleet.
        let fleet_slack = open_bins_count as f64 * mean_residual;
        let usable_slack = fitting_bins_count as f64 * mean_residual;
        if usable_slack > item_size as f64 * 1.5 {
            score += 2.0 + (usable_slack / item_size.max(1) as f64).min(3.0) * 1.5;
        }
        if fleet_slack > cap * (open_bins_count as f64) * 0.35 && item_size as f64 <= cap * 0.4 {
            score += 2.5;
        }
        // NEW: if the best achievable leftover in a fresh bin equals the
        // item complement that a fitting bin would leave, prefer the open
        // bin (fresh bin gains nothing but costs a bin).
        if fitting_bins_count >= 1 {
            let fresh_leftover = bin_capacity.saturating_sub(item_size);
            if fresh_leftover >= next_item_size && (fresh_leftover as f64) <= mean_residual * 1.2 {
                score += 3.0;
            }
        }
    }

    // Mean-residual deviation.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.5 + reach / cap * 4.5);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= bin_capacity / 8 && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.10 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.06 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount: residue under 15% of item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.07 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // Dead-space floor trap — residuals too small for the next item are
    // near-certain waste; escalate with stream density.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += 3.0 * (1.0 - dead_ratio) * (0.5 + density.min(1.0));
    }

    // Perfect-split preference.
    if post_residual > 0 && post_residual * 2 == bin_residual && next_item_size > 0
        && next_item_size <= post_residual {
        score -= 3.5;
    }

    // Residual absorption check — penalize leftovers landing in the gap
    // between next-item size and the fleet's average residual, since such
    // slivers are hard to recombine.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = post_residual as f64 - next_item_size as f64;
        if fit_margin > 0.0 && fit_margin < mean_residual * 0.5 {
            score += fit_margin * 0.12;
        }
    }

    // Harvest pressure — reward near-emptying bins when many are open.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = post_residual as f64 / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // NEW: dead-space ceiling — leftover that can hold next_item exactly once
    // but whose double-fill fails by a small margin is a trap; penalize
    // proportionally to how close the second copy comes.
    if next_item_size > 0 && post_residual >= next_item_size
        && post_residual < 2 * next_item_size && bin_residual != bin_capacity {
        let miss = (2 * next_item_size - post_residual) as f64;
        if miss <= tenth as f64 {
            score += miss * 0.22 * (1.0 - progress);
        }
    }

    // NEW: fleet-consolidation pull — when the fleet is dense in open bins,
    // extra-reward bins whose post-residual matches the next item exactly,
    // chaining closures and shrinking the open-bin count.
    if open_bins_count > 6 && next_item_size > 0 && post_residual == next_item_size {
        score -= 2.5 + 0.15 * (open_bins_count as f64).min(15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist that fit,
    // unless this bin is the last chance (fitting_bins_count == 1).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 1 {
            score += 30.0;
        } else if fitting_bins_count == 1 {
            score += 12.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it before opening a new bin.
        score -= 15.0;
    }

    // Open-bins pressure: fewer open bins is better; mild additive penalty scaled by count.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item could use the post_residual, reward leaving it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if next_item_size > item_size && post_residual > 0 {
            score += 4.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already tight; prefer filling it rather than spreading.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual - 10.0 {
        score -= 5.0;
    } else if bin_res_f > mean_residual + 10.0 {
        score += 3.0;
    }

    // Late-stream tightening: be more conservative as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 1.0 - progress;

    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;

    // Perfect / near-perfect closure tiers.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < fortieth {
        score -= 200.0;
    } else if post_residual < tenth {
        score -= 60.0;
    }

    // Lookahead chain rewards with sharpened slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 500.0;
        } else if slack < cap * 0.1 {
            score -= 120.0;
        } else if slack < cap * 0.25 {
            score -= 60.0;
        } else {
            score -= slack * 0.17;
        }
        // Triple-chain probe.
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead-space: leftover too small for next item is likely waste.
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += 40.0 * (gap_norm(post_residual, next_item_size)) * (0.6 + 0.4 * horizon);
        score += 3.0 * (1.0 - dead_ratio.min(1.0));
        // Fragmentation index.
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        score += 60.0 * (1.0 - open_pressure) + 17.0 + 10.0 * progress;
        if item_size >= 60 {
            score -= 80.0;
        }
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        // Penalize opening a bin when the fleet's usable slack can absorb the item.
        let usable_slack = fitting_bins_count as f64 * mean_residual;
        if usable_slack > item_size as f64 * 1.5 {
            score += 2.0 + (usable_slack / item_size.max(1) as f64).min(3.0) * 1.5;
        }
        // Fresh-bin leftover divisibility.
        let fresh_left = bin_capacity.saturating_sub(item_size);
        if fresh_left % 10 == 0 { score -= 2.0; }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let pair_left = bin_capacity - item_size - next_item_size;
            if pair_left == 0 {
                score -= 15.0;
            } else if pair_left <= twentieth {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Dead-space ratio term: quadratic + cubic waste pressure.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = pr / cap;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        score += waste;
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Strand-ratio discount: small residue relative to item is strong compaction.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = pr / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
    }

    // Harvest pressure: reward nearly emptying a bin.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = pr / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * horizon);
        }
    }

    // Dead-space delta vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        if pr < mean_residual {
            score -= (mean_residual - pr) * 0.10 * horizon;
        } else {
            score += (pr - mean_residual) * 0.06 * horizon;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * horizon;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    score
}

fn gap_norm(post_residual: u32, next_item_size: u32) -> f64 {
    let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
    (gap / 100.0).min(1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight packing (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the leftover space.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Smooth penalty proportional to mismatch, normalized by capacity.
            score += diff * 0.35;
        }
        // If next item cannot fit in the post-residual, the leftover is dead space
        // unless it's small enough to be negligible.
        if (next_item_size as f64) > post_residual as f64 {
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 10.0 {
                score -= 8.0; // tiny leftover is fine (near-perfect fill)
            } else {
                score += dead * 0.5; // unusable mid-size dead space penalized
            }
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.1;
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // "loose" bins; using them for a tight fit is good, leaving them loose is bad.
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual as f64 - item_size as f64).max(0.0) * 0.2;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a good fit. Make the empty bin moderately attractive for large items,
    // unattractive for small items.
    if bin_residual == bin_capacity {
        // Empty bin score: baseline plus penalty scaled by how much space would
        // remain compared to mean residual of open bins.
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 {
            let diff = ((bin_capacity - item_size) as i64 - next_item_size as i64).abs() as f64;
            if diff == 0.0 {
                score -= 40.0; // fresh bin perfectly sets up next item
            } else {
                score += diff * 0.3;
            }
        }
        // Prefer opening new bins early in the stream / when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // Discard new-bin option if many bins already fit the item well.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Small global tie-breaker toward denser bins.
    score += (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Capacity-relative dead space bands with sharpened near-full tiers.
    let fifth = bin_capacity / 5;
    let third = bin_capacity / 3;
    let tenth = bin_capacity / 10;
    let twentieth = bin_capacity / 20;
    let fortieth = bin_capacity / 40;
    let eighth = bin_capacity / 8;
    if post_residual == 0 {
        score -= 38.0;
    } else if post_residual < fortieth {
        score += 6.0 + (fortieth - post_residual) as f64 * 0.03;
    } else if post_residual < twentieth {
        score += 12.0 + (twentieth - post_residual) as f64 * 0.04;
    } else if post_residual < tenth {
        score += 30.0 + (tenth - post_residual) as f64 * 0.05;
    } else if post_residual < fifth {
        score += 38.0 + (fifth - post_residual) as f64 * 0.07;
    } else if post_residual <= third {
        score += 4.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0;
    } else {
        score -= 8.0;
    }

    // Divisibility rewards keep residuals reusable.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }

    // Lookahead chain rewards with slack tiers.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 34.0;
        } else if slack < cap * 0.1 {
            score -= 15.0;
        } else if slack < cap * 0.25 {
            score -= 7.0;
        } else {
            score -= slack * 0.17;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        if post_residual >= fifth { score += 9.0; } else { score += 4.0; }
    } else {
        score += pr * 0.5;
    }

    // Last-chance bin: only fitting open bin -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0;
    }
    // Scarcity coupling.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity {
        let scarcity = (open_bins_count as f64 - fitting_bins_count as f64).max(0.0);
        score -= scarcity * 0.48;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 17.0 + 10.0 * progress;
        if item_size as f64 > cap * 0.7 {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 7.0;
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 11.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual < fifth && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count >= 3 {
            score += 4.0 + fitting_bins_count as f64 * 0.55;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 3.0;
        }
        if item_size <= tenth && next_item_size > 0 {
            score += 5.0;
        }
        if item_size as f64 > cap * 0.85 && fitting_bins_count == 0 {
            score -= 6.0;
        }
        let sprawl = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
        if sprawl > 0.6 && item_size as f64 <= cap * 0.6 {
            score += 6.0 * (sprawl - 0.6).min(1.0);
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left == 0 {
                score -= 15.0;
            } else if fresh_left <= twentieth {
                score -= 6.0;
            }
        }
        let fresh_left2 = bin_capacity.saturating_sub(item_size);
        if fresh_left2 % 10 == 0 { score -= 2.0; }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 <= cap * 0.5 {
            if mean_residual < cap * 0.12 {
                score -= 5.0;
            }
        }
        if next_item_size > 0 {
            let fresh_left3 = bin_capacity.saturating_sub(item_size);
            if fresh_left3 < next_item_size && mean_residual >= next_item_size as f64 {
                score += 4.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 8.0;
        }
        if fresh_left2 > 0 && fresh_left2 % 10 == 0 && fresh_left2 <= twentieth {
            score -= 4.0;
        }
        // Penalize opening a bin when fleet mean residual could absorb the item.
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 6.0;
        }
        // Open-bin avoidance scales with usable fleet slack.
        let fleet_slack = open_bins_count as f64 * mean_residual;
        let usable_slack = fitting_bins_count as f64 * mean_residual;
        if usable_slack > item_size as f64 * 1.5 {
            score += 2.0 + (usable_slack / item_size.max(1) as f64).min(3.0) * 1.5;
        }
        if fleet_slack > cap * (open_bins_count as f64) * 0.35 && item_size as f64 <= cap * 0.4 {
            score += 2.5;
        }
        // NEW: refuse a fresh bin when any open bin's residual leaves a
        // smaller dead gap than a fresh bin would (post_residual == cap-item).
        if fitting_bins_count >= 1 {
            let fresh_dead = bin_capacity.saturating_sub(item_size) as f64;
            let fleet_best_gap = (mean_residual * 0.8).min(fresh_dead);
            if fresh_dead > 0.0 && fleet_best_gap < fresh_dead * 0.5 {
                score += (fresh_dead - fleet_best_gap * 2.0).max(0.0) * 0.08;
            }
        }
    }

    // Mean-residual deviation.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.07;
    } else {
        score += (-dev) * 0.02;
    }

    if bin_residual % 10 == 0 && item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Waste-forecast: unusable residual, stronger early.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < fifth {
        let horizon = 1.0 - progress;
        score += 5.0 + 4.5 * horizon;
    }

    // Global sprawl control.
    if open_bins_count as f64 > progress * total_items.max(1) as f64 * 0.55 {
        score += pr * 0.13;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Late-stream tightening.
    if step_index + 5 >= total_items {
        score += pr * 0.32;
    }

    // Size-matched pairing bonus.
    let complement = bin_residual.saturating_sub(item_size);
    if complement > 0 && complement <= twentieth {
        score -= 5.0;
    } else if complement > 0 && complement <= tenth {
        score -= 2.0;
    }

    // Large-item urgency.
    if item_size as f64 > cap * 0.5 && bin_residual != bin_capacity {
        score -= 3.0 + 3.0 * (item_size as f64 / cap);
    }

    // Two-item lookahead chain.
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        let chain_slack = bin_residual - item_size - next_item_size;
        if chain_slack == 0 {
            score -= 20.0;
        } else if chain_slack <= twentieth {
            score -= 12.0;
        } else if chain_slack <= tenth {
            score -= 9.0;
        }
        let two_chain = item_size + 2 * next_item_size;
        if two_chain <= bin_residual {
            let slack2 = bin_residual - two_chain;
            if slack2 == 0 {
                score -= 8.0;
            } else if slack2 <= tenth {
                score -= 4.0;
            }
        }
    }

    // Residual-shape trap.
    if post_residual > 0 && post_residual < tenth {
        let horizon = 1.0 - progress;
        score += 2.0 + 3.0 * horizon;
    }

    if post_residual == 0 && next_item_size > 0 && item_size <= tenth {
        score -= 4.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < cap * 0.05 {
            score -= 3.0;
        }
    }

    // Mid-band trap.
    if next_item_size > 0 && post_residual > third && post_residual <= bin_capacity / 2
        && post_residual < item_size + next_item_size {
        score += 3.0;
    }

    // Pair-closure bonus.
    if next_item_size > 0 && bin_residual >= item_size + next_item_size
        && bin_residual - item_size - next_item_size == 0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Adaptive tightness.
    if mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score += (cap * 0.25 - mean_residual) * 0.4;
    }

    // Residual-entropy steering.
    if next_item_size > 0 && next_item_size <= tenth && post_residual >= next_item_size {
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % next_item_size == 0 { score -= 2.5; }
    }

    // Dead-space ratio term: quadratic + cubic waste pressure, horizon-tuned.
    if post_residual > 0 && bin_residual != bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        let horizon = 1.0 - progress;
        let mut waste = waste_ratio * waste_ratio * 13.5 * horizon
            + waste_ratio * waste_ratio * waste_ratio * 6.0 * horizon;
        if next_item_size > 0 && post_residual >= next_item_size {
            waste *= 0.5;
        }
        if progress > 0.15 && progress < 0.85 {
            waste *= 1.25;
        }
        // NEW: extra cubic pressure on residuals that no plausible future
        // item can fill (below the observed small-item scale).
        if next_item_size > 0 && post_residual < next_item_size && waste_ratio < 0.12 {
            waste *= 1.35;
        }
        score += waste;
    }

    // Residual-floor guard.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over > 0 && over <= 3 {
            score += 2.5;
        }
    }

    // Horizon-weighted fill-pressure.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        let horizon = 1.0 - progress;
        let reach = (post_residual - next_item_size) as f64;
        score -= horizon * (2.5 + reach / cap * 4.5);
    }

    // Near-closure acceleration.
    if bin_residual != bin_capacity && post_residual > 0
        && post_residual <= eighth && next_item_size > 0
        && next_item_size > post_residual {
        score += 3.0;
    }

    // Residual-entropy banding.
    if post_residual > 0 && bin_residual != bin_capacity {
        let band = (post_residual as f64 - mean_residual).abs();
        if band < cap * 0.08 {
            score -= 2.0 * (1.0 - band / (cap * 0.08));
        }
    }

    // Triple-chain probe.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size && after_next <= tenth {
            score -= 3.0;
        }
    }

    // Exact-fill sweep.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation index.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (open_bins_count as f64).min(20.0) * 0.25;
    }

    // Dead-space delta coupling vs fleet average.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        let avg_waste = mean_residual;
        let this_waste = post_residual as f64;
        if this_waste < avg_waste {
            score -= (avg_waste - this_waste) * 0.10 * (1.0 - progress);
        } else {
            score += (this_waste - avg_waste) * 0.06 * (1.0 - progress);
        }
    }

    // Large-item rescue.
    if item_size as f64 > cap * 0.6 && post_residual > 0 && post_residual <= twentieth
        && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Strand-ratio discount.
    if bin_residual != bin_capacity && post_residual > 0 {
        let strand_ratio = post_residual as f64 / item_size.max(1) as f64;
        if strand_ratio < 0.15 {
            let mid = 1.0 - (progress - 0.5).abs() * 2.0;
            score -= (0.15 - strand_ratio) * item_size as f64 * 0.12 * (0.6 + 0.4 * mid);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            if post_residual < 2 * next_item_size {
                let dead = (post_residual - next_item_size) as f64;
                score += dead * 0.07 * (1.0 - progress);
            }
        }
    }

    // Residual-reusability forecast vs fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && mean_residual > 0.0 && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 2.0 * (1.0 - progress);
    }

    // Dead-space floor trap with density escalation.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let density = open_bins_count as f64 / (total_items.max(1) as f64).max(1.0);
        let dead_ratio = post_residual as f64 / next_item_size as f64;
        score += 3.0 * (1.0 - dead_ratio) * (0.5 + density.min(1.0));
    }

    // Perfect-split preference.
    if post_residual > 0 && post_residual * 2 == bin_residual && next_item_size > 0
        && next_item_size <= post_residual {
        score -= 3.5;
    }

    // Residual absorption check vs mean-residual neighborhood.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = post_residual as f64 - next_item_size as f64;
        if fit_margin > 0.0 && fit_margin < mean_residual * 0.5 {
            score += fit_margin * 0.12;
        }
    }

    // Harvest pressure — reward near-emptied bins when many are open.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        let tidy = post_residual as f64 / cap;
        if tidy < 0.05 {
            score -= (0.05 - tidy) * cap * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // NEW: compaction gradient — prefer bins whose residual shrinks by the
    // largest fraction, scaling with stream horizon; drives consolidation
    // rather than merely minimizing absolute leftover.
    if bin_residual != bin_capacity && bin_residual > 0 {
        let shrink = item_size as f64 / bin_residual as f64;
        score -= shrink * 3.0 * (0.4 + 0.6 * (1.0 - progress));
    }

    // NEW: late-stream exactness — as the stream ends, only near-perfect
    // fits are worth disturbing existing bins for.
    if progress > 0.8 && bin_residual != bin_capacity && post_residual > 0 {
        let exactness = 1.0 - post_residual as f64 / cap;
        score += (1.0 - exactness) * 6.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // wasted space relative to next item
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins below mean residual (keeps big holes free)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be conservative; late, pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: open new bins only when existing fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.55 && post_residual < 45;
        score = if poor_fit { -5.0 } else { 60.0 };
    }

    score
}

